/* Current-semester subject count (official schedule). */
const CURRENT_SUBJECT_COUNT = SUBJECTS.filter((s) => s.semester === "current").length;

/** Official current-semester subject count (defensive for Stats.Live). */
function getCurrentSubjectCount() {
  try { return CURRENT_SUBJECT_COUNT; } catch (e) { return 0; }
}

/* Expose for the AI assistant (assistant.js) and Stats.Live. */
window.PLATFORM_SUBJECTS = SUBJECTS;

/* ---- Render all subject cards from the registry (single source) ---- */
(function renderSubjectsGrid() {
  "use strict";
  const grid = document.getElementById("subjectsGrid");
  if (!grid) return;
  const escS = (v) => escHtml(String(v));
  const displayTime = (v) => (typeof formatDisplayTime === "function"
    ? formatDisplayTime(v)
    : String(v == null ? "" : v));

  /* Seeded question counts so cards never show empty badges before
     Stats.Live overwrites them from the live question bank. */
  const COUNT_SEED = { "260210030702": 32, "260210030802": 32, "260210030902": 24, "260210031002": 28, "260210031102": 28 };

  function materialsHtml(s) {
    const data = (typeof window !== "undefined" && window.PLATFORM_CURRENT_SEMESTER) || {};
    const subject = (data.subjects || []).find((item) => item.code === s.code);
    const materials = subject && Array.isArray(subject.materials) ? subject.materials : [];
    if (!materials.length) return `<span class="card-link is-soon" title="سيتم إضافة المحتوى قريبًا">تحميل التجميعات <svg class="ui-ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></span>`;
    const items = materials.map((material, index) => {
      const label = material.title && (material.title.ar || material.title.en) || `الفصل ${index + 1}`;
      return `<a class="chapter-download" href="${escS(material.path || "")}" target="_blank" rel="noopener"><span>${escS(label)}</span><b aria-hidden="true"><svg class="ui-ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></b></a>`;
    }).join("");
    return `<details class="card-materials"><summary class="card-link card-materials-trigger">تحميل التجميعات <span aria-hidden="true"><svg class="ui-ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/></svg></span></summary><div class="chapter-menu">${items}</div></details>`;
  }

  function linksHtml(s) {
    let html = "";
    if (s.contentStatus === "available" && s.quizKey) {
      const n = COUNT_SEED[s.quizKey] || "";
      html += `<a href="#quiz" class="card-link" data-quiz-jump="${escS(s.quizKey)}">بنك الأسئلة <span class="res-count" data-res="${escS(s.quizKey)}">${n}</span></a>`;
    } else {
      html += `<span class="card-link is-soon" title="سيتم إضافة المحتوى قريبًا">بنك الأسئلة</span>`;
    }
    /* MODULE 61 · contextual entry point to the lecture access guide
       (translated by MODULE 22 on boot and on every locale switch). */
    html += `<a href="#guide" class="card-link is-guide" data-i18n="guide.cardChip">دليل المحاضرة</a>`;
    html += materialsHtml(s);
    html += `<span class="card-link is-soon" title="سيتم إضافة المحتوى قريبًا">الملخصات</span>`;
    return html;
  }

  function descHtml(s) {
    const meta = `رمز المقرر ${escS(s.code)} • ${s.creditHours} ساعات معتمدة • ${escS(s.day)} ${escS(displayTime(s.startTime))} – ${escS(displayTime(s.endTime))}`;
    return meta + (s.descriptionAr ? ` — ${escS(s.descriptionAr)}` : "");
  }

  function cardHtml(s) {
    const tags = "current " + s.tag;
    const label = "مادة ";
    return (
      `<article class="work-card reveal tilt" data-subj-code="${escS(s.id)}" data-tags="${escS(tags)}"` +
      (s.quizKey ? ` data-quiz="${escS(s.quizKey)}"` : "") +
      `>` +
      `<div class="work-card-inner">` +
      `<div class="work-thumb" style="--hue: ${s.hue}"><span class="thumb-label">${label}${s.panel}</span>` +
      `<img class="thumb-img" src="${escS(s.icon)}" alt="${escS(s.nameAr)}" onerror="this.onerror=null;this.src='images/icon-maskable.svg'" width="800" height="600" loading="lazy" decoding="async" /></div>` +
      `<div class="work-info">` +
      `<h3>${escS(s.nameAr)} <span class="arrow">↖</span></h3>` +
      `<p>${descHtml(s)}</p>` +
      `<span class="work-year">الترم الحالي</span>` +
      `<div class="card-links">${linksHtml(s)}</div>` +
      `</div>` +
      `</div>` +
      `</article>`
    );
  }

  grid.innerHTML = SUBJECTS.map(cardHtml).join("");
})();

/* ---------- 02a · IdbStore — IndexedDB key/value persistence ------ */
const IdbStore = (() => {
  const DB_NAME = "motmi-portal";
  const STORE = "kv";
  var _db = null;

  /**
   * Open (and memoise) the database, creating the store on first run.
   * @returns {Promise<IDBDatabase>} Resolves with an open connection.
   */
  function open() {
    if (_db) return Promise.resolve(_db);
    return new Promise((resolve, reject) => {
      if (!("indexedDB" in window)) return reject(new Error("no-idb"));
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(STORE)) req.result.createObjectStore(STORE);
      };
      req.onsuccess = () => { _db = req.result; resolve(_db); };
      req.onerror = () => reject(req.error || new Error("idb-open-failed"));
    });
  }

  /**
   * Run one operation against the key/value store.
   * @template T
   * @param {"readonly"|"readwrite"} mode Transaction mode.
   * @param {function(IDBObjectStore): IDBRequest} fn Operation factory.
   * @returns {Promise<T>} Request result.
   */
  function tx(mode, fn) {
    return open().then(
      (db) =>
        new Promise((resolve, reject) => {
          const t = db.transaction(STORE, mode);
          const req = fn(t.objectStore(STORE));
          req.onsuccess = () => resolve(req.result);
          req.onerror = () => reject(req.error);
        })
    );
  }

  return {
    /** Read a value by key. @param {string} key @returns {Promise<*>} */
    get(key) { return tx("readonly", (s) => s.get(key)); },
    /** Write a value under a key. @param {string} key @param {*} val @returns {Promise<void>} */
    set(key, val) { return tx("readwrite", (s) => s.put(val, key)).then(() => undefined); },
    /** Delete a key. @param {string} key @returns {Promise<void>} */
    del(key) { return tx("readwrite", (s) => s.delete(key)).then(() => undefined); },
    /**
     * One-time migration of legacy quiz data from localStorage.
     * @returns {Promise<void>}
     */
    async migrateFromLocalStorage() {
      try {
        const raw = localStorage.getItem(`${Store.NS}:quiz`);
        if (!raw) return;
        const existing = await this.get("quiz");
        if (!existing) await this.set("quiz", JSON.parse(raw));
        localStorage.removeItem(`${Store.NS}:quiz`);
      } catch {}
    }
  };
})();

/* ---------- 02b · WorkerBridge — offload heavy computation ------ */
const WorkerBridge = (() => {
  var _worker = null;

  /**
   * Lazily create the Web Worker.
   * @returns {Worker|null} Worker instance or null if unsupported.
   */
  function getWorker() {
    if (_worker) return _worker;
    if (!window.Worker || location.protocol === "file:") return null;
    try { _worker = new Worker("./worker.js"); } catch { return null; }
    return _worker;
  }

  /**
   * Send a task to the worker and await its response.
   * @param {string} type Task type ("hash"|"password"|"cidr").
   * @param {*} payload Data for the task.
   * @returns {Promise<*>} Computed result or null if no worker.
   */
  function run(type, payload) {
    var w = getWorker();
    if (!w) return Promise.resolve(null);
    return new Promise(function (resolve, reject) {
      var id = Math.random().toString(36).slice(2, 11);
      var settled = false;
      /**
       * Route worker messages by correlation ID.
       * @param {MessageEvent} e Worker message event.
       * @returns {void}
       */
      function onMsg(e) {
        if (e.data.id !== id) return;
        cleanup();
        if (e.data.error) reject(new Error(e.data.error));
        else resolve(e.data.result);
      }
      /** Reject on worker-level failure so callers can fall back. @returns {void} */
      function onErr() {
        cleanup();
        reject(new Error("worker-failed"));
      }
      function cleanup() {
        settled = true;
        w.removeEventListener("message", onMsg);
        w.removeEventListener("error", onErr);
      }
      w.addEventListener("message", onMsg);
      w.addEventListener("error", onErr);
      if (settled) return;
      try {
        w.postMessage({ id: id, type: type, payload: payload });
      } catch (err) {
        /* e.g. the worker was terminated between getWorker() and the
           post — release the listeners and reject so callers can
           fall back to the main thread. */
        cleanup();
        reject(err);
      }
    });
  }

  return { run: run };
})();

/* ---------- 03 · Sfx ---------------------------------------- */
/* Cues that matter (MODULE 03). Every sound is synthesised live with the
   Web Audio API — zero assets, offline-safe: FM bells for the tones,
   band-passed noise for the transients, one short shared shimmer echo
   for space, and a soft compressor on the bus so stacked cues never
   clip. Only meaningful learning feedback is voiced: quiz grades
   (good/bad), quiz timeout and the study-timer chime. Interface chrome
   (clicks, opens, scrolling, navigation) stays silent by design. */
const Sfx = (() => {
  let ctx = null;
  let master = null;
  let shimIn = null;
  let noiseBuf = null;
  let enabled = Store.get("sound", true) === true;
  let lastKind = "";
  let lastAt = 0;
  const stamps = [];

  const MAX_VOICES = 48;    /* flood guard: cues inside the window */
  const VOICE_WINDOW = 800; /* ms */
  const DUP_MS = 70;        /* same-cue de-bounce */

  /** Rolling cue count over the last window (prunes as it reads).
   *  @returns {number} */
  function voiceCount() {
    const now = Date.now();
    while (stamps.length && now - stamps[0] > VOICE_WINDOW) stamps.shift();
    return stamps.length;
  }

  /** Create/resume the shared AudioContext + bus after a gesture.
   *  @returns {AudioContext|null} */
  function ensureCtx() {
    if (!enabled) return null;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    if (!ctx) {
      try {
        ctx = new AC();
        master = ctx.createGain();
        master.gain.value = 0.16;
        const glue = ctx.createDynamicsCompressor ? ctx.createDynamicsCompressor() : null;
        if (glue) {
          try {
            glue.threshold.value = -18;
            glue.knee.value = 12;
            glue.ratio.value = 6;
            glue.attack.value = 0.003;
            glue.release.value = 0.12;
          } catch (e1) { /* params are progressive */ }
          master.connect(glue);
          glue.connect(ctx.destination);
        } else {
          master.connect(ctx.destination);
        }
        /* Shimmer bus: one short feedback echo shared by the bells. */
        shimIn = ctx.createGain();
        shimIn.gain.value = 1;
        const delay = ctx.createDelay(0.2);
        delay.delayTime.value = 0.048;
        const fb = ctx.createGain();
        fb.gain.value = 0.22;
        const lp = ctx.createBiquadFilter();
        lp.type = "lowpass";
        lp.frequency.value = 3800;
        shimIn.connect(delay);
        delay.connect(lp);
        lp.connect(fb);
        fb.connect(delay);
        lp.connect(master);
      } catch (e2) {
        ctx = null; master = null; shimIn = null;
        return null;
      }
    }
    if (ctx.state === "suspended") { try { ctx.resume(); } catch (e3) { /* stay silent */ } }
    return ctx;
  }

  /** Stereo panner when the engine has one. @returns {Object|null} */
  function panner(pan) {
    if (!ctx.createStereoPanner) return null;
    try {
      const p = ctx.createStereoPanner();
      p.pan.value = pan;
      return p;
    } catch (e) { return null; }
  }

  /** Connect a scheduled voice to the bus (+ optional shimmer send).
   *  @returns {void} */
  function route(node, send, pan) {
    stamps.push(Date.now());
    const panNode = (typeof pan === "number") ? panner(pan) : null;
    let tail = node;
    if (panNode) { node.connect(panNode); tail = panNode; }
    tail.connect(master);
    if (send > 0 && shimIn) {
      const s = ctx.createGain();
      s.gain.value = send;
      tail.connect(s);
      s.connect(shimIn);
    }
  }

  /** Exponential glide helper that never touches zero. @returns {void} */
  function glide(param, from, to, t0, dur) {
    param.setValueAtTime(Math.max(from, 1), t0);
    if (to !== from) param.exponentialRampToValueAtTime(Math.max(to, 1), t0 + dur);
  }

  /** One plucked FM bell (sine carrier + decaying sine modulator).
   *  @returns {void} */
  function bell(freq, t0, o) {
    o = o || {};
    const dur = o.dur || 0.34;
    const vol = (o.vol == null ? 0.4 : o.vol);
    const carrier = ctx.createOscillator();
    const mod = ctx.createOscillator();
    const mg = ctx.createGain();
    const cg = ctx.createGain();
    carrier.type = "sine";
    carrier.frequency.value = freq;
    mod.type = "sine";
    mod.frequency.value = freq * (o.ratio || 2.01);
    mg.gain.setValueAtTime(freq * (o.idx == null ? 1.6 : o.idx), t0);
    mg.gain.exponentialRampToValueAtTime(Math.max(freq * 0.01, 1), t0 + dur * 0.55);
    mod.connect(mg);
    mg.connect(carrier.frequency);
    cg.gain.setValueAtTime(0.0001, t0);
    cg.gain.linearRampToValueAtTime(vol, t0 + 0.008);
    cg.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    carrier.connect(cg);
    route(cg, o.send || 0, o.pan);
    mod.start(t0);
    carrier.start(t0);
    mod.stop(t0 + dur + 0.05);
    carrier.stop(t0 + dur + 0.05);
  }

  /** One band-passed noise sweep (shared noise buffer, built lazily).
   *  @returns {void} */
  function swish(f0, f1, t0, dur, o) {
    o = o || {};
    const vol = (o.vol == null ? 0.3 : o.vol);
    if (!noiseBuf) {
      const len = Math.max(1, Math.floor(ctx.sampleRate * 0.6));
      noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    }
    const src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    const f = ctx.createBiquadFilter();
    f.type = o.type || "bandpass";
    f.Q.value = (o.q == null ? 1.2 : o.q);
    glide(f.frequency, f0, f1, t0, dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + (o.attack || 0.006));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f);
    f.connect(g);
    route(g, o.send || 0, o.pan);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  /** One gliding tone blip. @returns {void} */
  function blip(f0, f1, t0, dur, o) {
    o = o || {};
    const vol = (o.vol == null ? 0.3 : o.vol);
    const osc = ctx.createOscillator();
    osc.type = o.type || "sine";
    glide(osc.frequency, f0, f1, t0, dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(vol, t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    route(g, o.send || 0, o.pan);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  /** Schedule one named cue on the bus. @returns {void} */
  function cue(kind, opt) {
    const t0 = ctx.currentTime + 0.004;
    const pan = opt.pan;
    switch (kind) {
      /* euphoric rising sparkle for a correct answer */
      case "good": {
        const run = [523.25, 659.25, 783.99, 1046.5];
        for (let i = 0; i < run.length; i++) {
          bell(run[i], t0 + i * 0.055, { vol: 0.34 - i * 0.02, dur: 0.42, send: 0.22 });
        }
        swish(5200, 6400, t0 + 0.12, 0.05, { vol: 0.08, q: 3 });
        break;
      }
      /* a gentle low five for a miss — honest, never punishing */
      case "bad":
        blip(349.23, 293.66, t0, 0.16, { vol: 0.3 });
        blip(233.08, 196, t0 + 0.09, 0.14, { vol: 0.22 });
        swish(900, 500, t0, 0.1, { vol: 0.1, q: 1.5 });
        break;
      /* time ran out — three dusty descending bells */
      case "timeout": {
        const fall = [392, 311.13, 261.63];
        for (let i = 0; i < fall.length; i++) {
          bell(fall[i], t0 + i * 0.13, { vol: 0.3, dur: 0.3, idx: 1.1 });
          swish(800, 500, t0 + i * 0.13, 0.08, { vol: 0.08, q: 2 });
        }
        break;
      }
      /* timer finish — a warm three-note ring */
      case "chime":
        bell(880, t0, { vol: 0.3, dur: 0.5, send: 0.3 });
        bell(1174.66, t0 + 0.16, { vol: 0.28, dur: 0.5, send: 0.3 });
        bell(880, t0 + 0.32, { vol: 0.22, dur: 0.6, send: 0.3 });
        break;
    }
  }

  return {
    get enabled() { return enabled; },
    set enabled(v) { enabled = !!v; },
    /** Unlock the context on the first user gesture. @returns {void} */
    prime() { try { ensureCtx(); } catch (e) { /* stay silent */ } },
    /**
     * Play a named cue.
     * @param {"good"|"bad"|"timeout"|"chime"} kind Cue name.
     * @param {Object=} opt Options: {intensity}, {dir}, {pan}.
     * @returns {void}
     */
    play(kind, opt) {
      try {
        const now = Date.now();
        if (kind === lastKind && now - lastAt < DUP_MS) return;
        if (!ensureCtx()) return;
        if (voiceCount() > MAX_VOICES) return;
        lastKind = kind;
        lastAt = now;
        cue(kind, opt || {});
      } catch (e) { /* audio is optional */ }
    }
  };
})();

/* ---------- 03b · Soundscape — only the cues that matter ---------- */

const primeAudio = (() => {
  /** Unlock the shared context on the first user gesture. @returns {void} */
  function prime() { try { Sfx.prime(); } catch (e) { /* stay silent */ } }
  document.addEventListener("pointerdown", prime, true);
  document.addEventListener("keydown", prime, true);
  return prime;
})();

/** Public surface — kept for tests, power users and future opt-ins.
 *  Speech cover from 2026: only meaningful learning feedback speaks
 *  (quiz grades / lesson checks, timeout, master timer chime). */
const Soundscape = {
  /** @param {string} kind Cue name. @param {Object=} opt Options. @returns {void} */
  play(kind, opt) { Sfx.play(kind, opt); },
  get enabled() { return Sfx.enabled; },
  setEnabled(v) {
    Sfx.enabled = !!v;
    try { Store.set("sound", !!v); } catch (e) { /* storage may be blocked */ }
    return Sfx.enabled;
  },
  prime() { try { primeAudio(); } catch (e) { /* no-op */ } }
};
try { window.NovaSound = Soundscape; } catch (e) { /* non-browser embed */ }
/* ---------- end 03b · Soundscape ---------------------------- */

/* ============================================================
   MODULE 05 · PointerFX — shared pointer + idle-aware rAF loop
   ------------------------------------------------------------
   Cursor / tilt / magnetic modules only record cheap target
   values; one requestAnimationFrame loop applies them and
   pauses itself when nothing is animating (no CPU thrash).
   ============================================================ */
const prefersReducedMotion =
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const pointerFine = window.matchMedia("(pointer: fine)").matches;

const pointer = { tx: 0, ty: 0, active: false };
/** Hooks returning true while they still have frame work. */
const renderHooks = [];
const fxLoop = { running: false };

/** Start the shared render loop if idle. @returns {void} */
function startFxLoop() {
  if (fxLoop.running) return;
  fxLoop.running = true;
  requestAnimationFrame(fxTick);
}

/** Run all hooks; keep looping only while work remains. @returns {void} */
function fxTick() {
  let work = false;
  for (let i = 0; i < renderHooks.length; i++) {
    if (renderHooks[i]() === true) work = true;
  }
  if (work) requestAnimationFrame(fxTick);
  else fxLoop.running = false;
}

/**
 * Register a per-frame hook.
 * @param {Function} hook Frame callback; return truthy to continue.
 * @returns {void}
 */
function addRenderHook(hook) { renderHooks.push(hook); }

if (pointerFine && !prefersReducedMotion) {
  window.addEventListener("mousemove", (e) => {
    pointer.tx = e.clientX;
    pointer.ty = e.clientY;
    pointer.active = true;
    startFxLoop();
  }, { passive: true });
}


/* ============================================================
   MODULE 06 · Cursor — custom cursor, JS-gated activation
   ============================================================ */
(function initCursor() {
  const curDot = document.querySelector(".cursor-dot");
  const curRing = document.querySelector(".cursor-ring");
  if (!curDot || !curRing || !pointerFine || prefersReducedMotion) return;

  /* Success → allow CSS to hide the native cursor */
  document.documentElement.setAttribute("data-cursor-active", "true");

  pointer.tx = -100; pointer.ty = -100;
  curDot.style.left = "-100px"; curDot.style.top = "-100px";
  curRing.style.left = "-100px"; curRing.style.top = "-100px";

  let ringX = -100, ringY = -100;

  addRenderHook(() => {
    curDot.style.left = pointer.tx + "px";
    curDot.style.top = pointer.ty + "px";
    ringX += (pointer.tx - ringX) * 0.18;
    ringY += (pointer.ty - ringY) * 0.18;
    curRing.style.left = ringX + "px";
    curRing.style.top = ringY + "px";
    return Math.abs(pointer.tx - ringX) > 0.2 || Math.abs(pointer.ty - ringY) > 0.2;
  });

  $$(".work-card-inner").forEach((el) => {
    el.addEventListener("mouseenter", () => curRing.classList.add("is-hovering"));
    el.addEventListener("mouseleave", () => curRing.classList.remove("is-hovering"));
  });
})(); 
 

/* ============================================================
   MODULES 08-09 · Reveal & navbar · animated counters
   ============================================================ */
(function initRevealAndNav() {
  const nav = $id("nav");
  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      io.unobserve(entry.target);
    });
  }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });

  $$(".reveal").forEach((el) => io.observe(el));

    /** Toggle the navbar's frosted state. On the hero (dark backdrop) the
      nav stays transparent until scrolled > 40px; on all other views the
      light background requires a always-frosted nav for text contrast.
      @returns {void} */
  function onScroll() {
    if (!nav) return;
    const hero = $id("hero");
    const onHero = hero && hero.classList.contains("is-active");
    if (onHero) nav.classList.toggle("is-scrolled", window.scrollY > 40);
    else nav.classList.add("is-scrolled");
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();
})();

(function initCounters() {
  const els = $$("[data-count]");
  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      const el = entry.target;
      const target = parseFloat(el.dataset.count || "0");
      if (!isFinite(target)) return; /* non-numeric hooks ("questions"…) are owned by Stats.Live */
      const duration = 1400;
      const start = performance.now();
      function tick(now) {
        const t = Math.min((now - start) / duration, 1);
        el.textContent = String(Math.round(target * (1 - Math.pow(1 - t, 3))));
        if (t < 1) requestAnimationFrame(tick);
        else el.textContent = String(target);
      }
      requestAnimationFrame(tick);
      io.unobserve(el);
    });
  }, { threshold: 0.6 });
  els.forEach((el) => io.observe(el));
})();

/* ============================================================
   MODULE 10 · Mobile menu drawer
   ============================================================ */
(function initMobileMenu() {
  const burger = $id("navBurger");
  const menu = $id("mobileMenu");
  const trap = burger && menu ? createFocusTrap([burger, menu], {
    background: () => $$(".skip-link, .preloader, .cursor-dot, .cursor-ring, .nav-inner > *:not(#navBurger), main, .footer, #toTop, #assistantRoot, #onboardingOverlay, #searchOverlay, #searchDialog")
  }) : null;

  /**
   * Open/close the drawer and lock body scrolling.
   * @param {boolean} open Desired state.
   * @returns {void}
   */
  function setMenu(open) {
    if (!menu || !burger) return;
    if (open && anotherOverlayOpen(menu)) return;
    menu.classList.toggle("is-open", open);
    burger.classList.toggle("is-open", open);
    burger.setAttribute("aria-expanded", String(open));
    burger.setAttribute("aria-label", open ? "إغلاق القائمة" : "فتح القائمة");
    menu.setAttribute("aria-hidden", String(!open));
    try { menu.inert = !open; } catch { /* inert is progressive */ }
    if (open) menu.removeAttribute("inert");
    else menu.setAttribute("inert", "");
    document.body.style.overflow = open ? "hidden" : "";
    if (open) {
      trap.activate();
      /* Move focus into the drawer so keyboard users are not stranded. */
      trap.focusFirst("a, button");
    } else {
      trap.deactivate();
    }
  }

  if (burger && menu) {
    burger.addEventListener("click", () => setMenu(!menu.classList.contains("is-open")));
    $$("a", menu).forEach((a) => a.addEventListener("click", () => setMenu(false)));
    /* Escape closes the drawer and returns focus to the burger. */
    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape" || !menu.classList.contains("is-open")) return;
      setMenu(false);
      burger.focus({ preventScroll: true });
    });
  }
})();

/* ============================================================
   MODULE 10b · Nav "More" dropdown
   Renders nothing: it only adds accessible open/close behaviour for
   the compact top navigation (<details id="navMoreDetails">).
   Closes on outside click, Escape, or choosing any link.
   ============================================================ */
(function initNavMore() {
  const details = $id("navMoreDetails");
  if (!details) return;
  const summary = details.querySelector("summary");
  if (!summary) return;

  /** Reflect native open state for assistive tech. */
  function sync() {
    summary.setAttribute("aria-expanded", details.open ? "true" : "false");
  }
  sync();

  details.addEventListener("toggle", sync);

  /* Close on link click */
  details.querySelectorAll("a").forEach((a) => {
    a.addEventListener("click", () => {
      details.open = false;
      sync();
    });
  });

  /* Close on click outside */
  document.addEventListener("click", (e) => {
    if (!details.open) return;
    if (!details.contains(e.target)) {
      details.open = false;
      sync();
    }
  });

  /* Close on Escape key */
  details.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && details.open) {
      details.open = false;
      sync();
      summary.focus({ preventScroll: true });
    }
  });

  /* MODULE 95 · hover-to-open on fine pointers: the summary stays fully
     clickable; hovering now previews the menu after a short intent
     delay and auto-closes after leaving. Click, outside-click and
     Escape behaviours above remain unchanged. Reduced motion users keep
     native behaviour open/close (CSS already disables its transitions). */
  if (typeof pointerFine !== "undefined" && pointerFine) {
    let tOpen = null;
    let tClose = null;
    details.addEventListener("mouseenter", () => {
      if (tClose) { clearTimeout(tClose); tClose = null; }
      if (!details.open && !tOpen) {
        tOpen = setTimeout(() => {
          tOpen = null;
          if (!details.open) details.open = true;
        }, 140);
      }
    });
    details.addEventListener("mouseleave", () => {
      if (tOpen) { clearTimeout(tOpen); tOpen = null; }
      if (tClose) clearTimeout(tClose);
      tClose = setTimeout(() => {
        tClose = null;
        if (details.open) details.open = false;
      }, 220);
    });
  }
})();

/* ============================================================
   MODULE 10c · NavResume + reading progress (MODULE 95)
   - NavResume: a compact "continue" pill in the top bar that reopens
     the last visited view (localStorage, deep links like "#lesson/…"
     preserved). Hidden while the user is already on that view and when
     the last view is the home hero.
   - Reading progress: a hairline gradient bar under the navbar that
     reflects scroll position (RTL/LTR origin handled in CSS via dir).
   Both are additive: no existing module behaviour changes. The view
   events arrive after MODULE 33 boots, so Lang/Store exist by then.
   ============================================================ */
(function initNavResume() {
  const chip = $id("navResume");
  const labelEl = $id("navResumeTarget");
  if (!chip || !labelEl) return;

  const KEY = "nav.resume";
  const MAX_LABEL = 40;
  let saved = null;

  /** @returns {string} Current hash, never empty ("#hero" fallback). */
  function currentHash() {
    return location.hash && location.hash !== "#" ? location.hash : "#hero";
  }

  /** Safe translation with fallback (handlers run after Lang boots). */
  function t(key, fallback) {
    try {
      if (typeof Lang !== "undefined" && Lang && typeof Lang.t === "function") {
        return Lang.t(key);
      }
    } catch (e0) { /* Lang not ready yet */ }
    return fallback;
  }

  /**
   * Best-guess human label for the heading of an active view/lesson.
   * @param {string} viewId
   * @returns {string}
   */
  function snapshotLabel(viewId) {
    const view = $id(viewId);
    const el = view && view.querySelector("h1, h2, [data-view-heading]");
    if (!el) return "";
    return ((el.textContent || "").trim().replace(/\s+/g, " ")).slice(0, MAX_LABEL);
  }

  /**
   * MODULE 97 · live i18n label — when the stored hash matches a nav/menu/
   * sitemap anchor, use THAT anchor's current text (it was already i18n-
   * applied, so the chip re-reflects language switches for free). Heading
   * snapshots remain the fallback for deep runs (#lesson/…, #path/…).
   * @param {string} hash
   * @returns {string}
   */
  function navLabelForHash(hash) {
    if (!hash || hash === "#") return "";
    try {
      const el = document.querySelector('a[href="' + hash.replace(/"/g, '\\"') + '"]');
      if (el && (el.closest("nav, .mobile-menu, .footer-links, .quick-strip") != null)) {
        const s = ((el.textContent || "").trim().replace(/\s+/g, " "));
        if (s) return s.slice(0, MAX_LABEL);
      }
    } catch (eSel) { /* malformed hash — swallow and fall back */ }
    return "";
  }

  /** Reflect the stored position on the chip; fitCheck decides visibility. */
  function paint() {
    const show = !!(saved && saved.hash && saved.hash !== currentHash());
    chip.href = show && saved ? saved.hash : "#";
    if (show) {
      const label = navLabelForHash(saved.hash) || saved.label || "";
      labelEl.textContent = label;
      try {
        chip.setAttribute("aria-label", `${t("nav.resumeChip", "متابعة")}: ${label || currentHash()}`);
      } catch (e1) { /* aria is best-effort */ }
    }
    scheduleFitCheck();
  }

  /**
   * Capture the position after a view switch, then refresh lesson
   * labels once module 40 renders the lesson content.
   * @param {CustomEvent} e
   * @returns {void}
   */
  function onViewChanged(e) {
    const viewId = String((e && e.detail && e.detail.viewId) || "").replace(/^#/, "");
    if (!viewId || viewId === "hero") { paint(); return; }

    saved = saved || {};
    saved.hash = currentHash();
    saved.label = snapshotLabel(viewId);
    Store.set(KEY, saved);
    paint();

    /* Lesson/path headings render asynchronously — refresh once. */
    if (viewId === "lesson" || viewId === "path") {
      const targetHash = saved.hash;
      setTimeout(() => {
        if (currentHash() !== targetHash) return;
        const label = snapshotLabel(viewId);
        if (label && saved && saved.hash === targetHash) {
          saved.label = label;
          Store.set(KEY, saved);
          paint();
        }
      }, 700);
    }
  }

  document.addEventListener("nova:view-changed", onViewChanged);

  /* MODULE 97 · refresh the chip with the current language — nav anchors
     re-applied their localized text before these listeners run. Lang is
     declared further down the bundle (TDZ at parse time), so hook it
     lazily and retry once DOMContentLoaded fires. */
  let langHooked = false;
  function hookLangRepaint() {
    if (langHooked) return false;
    try {
      if (typeof Lang !== "undefined" && Lang && typeof Lang.onSwitch === "function") {
        Lang.onSwitch(() => paint());
        langHooked = true;
      }
    } catch (eLang) { /* const not initialized yet — retry on DOMContentLoaded */ }
    return langHooked;
  }
  if (!hookLangRepaint()) {
    document.addEventListener("DOMContentLoaded", hookLangRepaint, { once: true });
  }

  /* Fit check: the top bar is a closed flex row. When the links side
     (nav-main) overflows — e.g. long EN labels — hide the pill instead
     of letting it collide with the menu (re-checked on resize). */
  let squeezed = false;
  const navInner = chip.closest(".nav-inner");
  const navMain = navInner ? navInner.querySelector(".nav-main") : null;
  const navRoot = navInner ? navInner.closest(".nav") : null;
  const moreDetails = navInner ? navInner.querySelector("#navMoreDetails") : null;

  function scheduleFitCheck() {
    if (typeof requestAnimationFrame === "function") {
      requestAnimationFrame(fitCheck);
    } else {
      fitCheck();
    }
  }

  /** Deterministic single-pass fit: measure the row bare → squeeze it if
      it alone overflows → probe the pill (invisible) → final visibility. */
  function fitCheck() {
    if (!navMain) return;
    const wanted = !!(saved && saved.hash && saved.hash !== currentHash());
    /* The open dropdown is an absolutely positioned descendant whose
       panel box inflates nav-main.scrollWidth — measure with it shut. */
    const wasOpen = moreDetails && moreDetails.open;
    if (wasOpen) moreDetails.open = false;

    /* Sub-pixel/hairline shrink is invisible — only flag real collisions. */
    const DEFICIT = 12;

    /* Step 1 — the row's own need, pill and squeeze OFF the table. */
    chip.hidden = true;
    if (navRoot) navRoot.classList.remove("nav--squeeze");
    const squeeze = navMain.scrollWidth > navMain.clientWidth + DEFICIT;
    if (navRoot) navRoot.classList.toggle("nav--squeeze", squeeze);

    /* Step 2 — pill show/probe at its full natural width (invisible so
       nothing flickers); hide again when the row cannot host it. */
    let show = false;
    if (wanted) {
      chip.style.visibility = "hidden";
      chip.hidden = false;
      show = navMain.scrollWidth <= navMain.clientWidth + DEFICIT;
      chip.hidden = !show;
      chip.style.visibility = "";
    }
    squeezed = squeeze;

    if (wasOpen) moreDetails.open = true;
  }

  window.addEventListener("resize", () => {
    if (!squeezed) return;
    squeezed = false;
    /* Repaint from the stored state, then re-measure next frame. */
    paint();
    scheduleFitCheck();
  }, { passive: true });

  /* First paint may happen before layout settles — defer to rAF. */
  scheduleFitCheck();
})();

(function initNavProgress() {
  const bar = $id("navProgressBar");
  if (!bar) return;

  let ticking = false;

  function paint() {
    ticking = false;
    const doc = document.documentElement;
    const max = Math.max(1, (doc.scrollHeight || 0) - (window.innerHeight || 1));
    const p = Math.min(1, Math.max(0, (window.scrollY || 0) / max));
    bar.style.transform = "scaleX(" + p.toFixed(4) + ")";
  }

  /** Batch scroll storms into one rAF paint. @returns {void} */
  function schedule() {
    if (!ticking && typeof requestAnimationFrame === "function") {
      ticking = true;
      requestAnimationFrame(paint);
    } else if (typeof requestAnimationFrame !== "function") {
      paint();
    }
  }

  window.addEventListener("scroll", schedule, { passive: true });
  window.addEventListener("resize", schedule, { passive: true });
  document.addEventListener("nova:view-changed", () => {
    /* Views reset scroll and change document height */
    setTimeout(schedule, 60);
  });
  paint();
})();

 
/* ============================================================
   MODULES 11-12 · Tilt / Magnetic effects + Contact form
   ============================================================ */
(function initTilt() {
  if (!pointerFine || prefersReducedMotion) return;
  const MAX_TILT = 7;

  $$(".tilt").forEach((card) => {
    let cx = 0, cy = 0, hovering = false;
    card.addEventListener("mouseenter", () => { hovering = true; startFxLoop(); });
    card.addEventListener("mouseleave", () => { hovering = false; });

    addRenderHook(() => {
      let tx = 0, ty = 0;
      if (hovering) {
        const r = card.getBoundingClientRect();
        tx = (pointer.tx - r.left) / r.width - 0.5;
        ty = (pointer.ty - r.top) / r.height - 0.5;
      }
      cx += (tx - cx) * 0.16;
      cy += (ty - cy) * 0.16;
      const active = hovering || Math.abs(cx) > 0.001 || Math.abs(cy) > 0.001;
      if (active) {
        card.style.transform =
          `perspective(900px) rotateX(${(-cy * MAX_TILT).toFixed(2)}deg)` +
          ` rotateY(${(cx * MAX_TILT).toFixed(2)}deg) translateY(${hovering ? -5 : 0}px)`;
      } else if (card.style.transform) card.style.transform = "";
      return active;
    });
  });
})();

(function initMagnetic() {
  if (!pointerFine || prefersReducedMotion) return;
  const STRENGTH = 22;

  $$(".magnetic").forEach((btn) => {
    let cx = 0, cy = 0, hovering = false;
    btn.addEventListener("mouseenter", () => { hovering = true; startFxLoop(); });
    btn.addEventListener("mouseleave", () => { hovering = false; });

    addRenderHook(() => {
      let tx = 0, ty = 0;
      if (hovering) {
        const r = btn.getBoundingClientRect();
        tx = ((pointer.tx - (r.left + r.width / 2)) / r.width) * STRENGTH;
        ty = ((pointer.ty - (r.top + r.height / 2)) / r.height) * STRENGTH;
      }
      cx += (tx - cx) * 0.2;
      cy += (ty - cy) * 0.2;
      const active = hovering || Math.abs(cx) > 0.05 || Math.abs(cy) > 0.05;
      if (active) btn.style.transform = `translate(${cx.toFixed(1)}px, ${cy.toFixed(1)}px)`;
      else if (btn.style.transform) btn.style.transform = "";
      return active;
    });
  });
})();

(function initContactForm() {
  const form = $id("contactForm");
  const statusEl = $id("formStatus");
  const submitBtn = form ? form.querySelector(".form-submit") : null;
  if (!form || !statusEl) return;
  const fields = $$("input:not([type=hidden]), select, textarea", form);

  /** In-flight guard — blocks a second submit while a request is open. */
  let sending = false;

  /**
   * Render a status line under the form.
   * @param {string} msg Arabic message.
   * @param {boolean=} isError Error styling flag.
   * @returns {void}
   */
  function showStatus(msg, isError = false) {
    statusEl.textContent = msg;
    statusEl.classList.toggle("is-error", isError);
  }

  /**
   * Toggle the submit button's loading state.
   * @param {boolean} loading True to disable and show progress text.
   * @returns {void}
   */
  function setLoading(loading) {
    if (!submitBtn) return;
    submitBtn.disabled = loading;
    const label = submitBtn.querySelector(".submit-text") || submitBtn;
    label.textContent = loading ? Lang.t("contact.sending") : Lang.t("contact.submit");
    submitBtn.setAttribute("aria-busy", String(loading));
  }

  form.addEventListener("submit", async (e) => {
    e.preventDefault();

    /* Duplicate-submission guard (double click / Enter while in flight). */
    if (sending) return;

    /* Honeypot: silently accept but discard bot submissions. */
    const honeypot = form.querySelector('[name="_gotcha"]');
    if (honeypot && honeypot.value.trim()) return;

    let firstInvalid = null;
    fields.forEach((f) => {
      const g = f.closest(".form-field");
      const bad = !f.checkValidity();
      if (bad && !firstInvalid) firstInvalid = f;
      if (g) g.classList.toggle("has-error", bad);
      f.setAttribute("aria-invalid", bad ? "true" : "false");
    });
    if (!form.checkValidity()) {
      showStatus(Lang.t("contact.invalid"), true);
      if (firstInvalid && typeof firstInvalid.focus === "function") firstInvalid.focus();
      return;
    }

    setLoading(true);
    sending = true;
    const data = Object.fromEntries(new FormData(form));

    try {
      const res = await fetch(form.action, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({
          name: data.name,
          email: data.email,
          service: data.service,
          message: data.message,
          _subject: "مساهمة جديدة — منصة أمن المعلومات"
        })
      });
      if (!res.ok) throw new Error("HTTP " + res.status);
      showStatus(Lang.t("contact.sent"));
      form.reset();
    } catch (err) {
      showStatus(Lang.t("contact.error"), true);
    } finally {
      sending = false;
      setLoading(false);
    }
  });

  fields.forEach((f) => f.addEventListener("input", () => {
    const g = f.closest(".form-field");
    if (g) g.classList.remove("has-error");
    f.setAttribute("aria-invalid", "false");
  }));
})(); 
 
/* ============================================================
   MODULE 13 · QuizEngine — question bank (5 current-semester courses)
   Question shape: { q, ex, opts[4], a, t? (per-question seconds) }
   ============================================================ */
/* ============================================================
   Embedded fallback bank — mirrors data/quizzes.json schema.
   Question shape: { id, subjectId, difficulty, topic, q, ex,
   opts[4], a } (topic doubles as the category label).
   Keyed by the OFFICIAL course codes of the current-semester
   study plan — never by legacy subject keys. Used whenever the
   external file fails or validates empty.
   ============================================================ */
const MOCK_QUIZZES = {
  "260210030702": { name: "الخوارزميات", questions: [
    { id: "algo-001", subjectId: "260210030702", difficulty: "easy", topic: "intro", q: "ما التعريف الأدق للخوارزمية؟", opts: ["مجموعة مرتبة من العمليات المعرّفة والمعدودة والضرورية لحل مسألة","لغة برمجة عالية المستوى","جهاز إلكتروني للحساب","ملف تخزين للبيانات"], a: 0, ex: "الخوارزمية مجموعة مرتبة من العمليات المعرّفة والمعدودة والضرورية للوصول إلى النتيجة الصحيحة." },
    { id: "algo-002", subjectId: "260210030702", difficulty: "easy", topic: "describing", q: "أي شكل يمثل القرار (الشرط) في المخطط الانسيابي؟", opts: ["المستطيل","المعيّن","البيضاوي","متوازي الأضلاع"], a: 1, ex: "المعيّن للقرار، والمستطيل للعملية، ومتوازي الأضلاع للإدخال والإخراج، والبيضاوي للبداية والنهاية." },
    { id: "algo-003", subjectId: "260210030702", difficulty: "easy", topic: "control", q: "ماذا يسبب عدم تحديث متغير التحكم في حلقة ما دام شرطها صحيحًا؟", opts: ["توقف الحلقة فورًا","تكرارًا لا نهائيًا","خطأ في الإدخال","تخطي أول دورة"], a: 1, ex: "لكل حلقة تحديث لمتغير التحكم؛ إغفاله مع شرط صحيح دائمًا يوقع البرنامج في تكرار لا نهائي." },
    { id: "algo-004", subjectId: "260210030702", difficulty: "medium", topic: "search", q: "ما الشرط الأساسي لتشغيل البحث الثنائي؟", opts: ["أن تكون القائمة مرتبة","أن تكون القائمة فارغة","أن تكون القيم نصوصًا","أن يكون عدد العناصر زوجيًا"], a: 0, ex: "البحث الثنائي يستبعد نصف القائمة في كل خطوة، ولا يصح ذلك إلا على قائمة مرتبة." },
    { id: "algo-005", subjectId: "260210030702", difficulty: "medium", topic: "sorting", q: "في ترتيب الفقاعات لجدول من n عنصرًا، ما حدّ الحلقة الداخلية في المرور i؟", opts: ["n − 1 − i","n − i","i","n + i"], a: 0, ex: "بعد كل مرور يستقر عنصر في نهايته فتتقلص المقارنات بمقدار عنصر: n − 1 − i." },
    { id: "algo-006", subjectId: "260210030702", difficulty: "easy", topic: "arrays", q: "لماذا يكون شرط المرور على القائمة (i < الطول)؟", opts: ["لأن آخر موضع فعلي هو الطول − 1","لأن العد يبدأ من الواحد","لأن الطول متغيّر","لأن المصفوفة دائرية"], a: 0, ex: "المواضع تبدأ من الصفر، فآخر عنصر في الموضع الطول − 1، وi = الطول موضع لا وجود له." },
    { id: "algo-007", subjectId: "260210030702", difficulty: "easy", topic: "strings", q: "ما موضع آخر حرف في سلسلة عدد حروفها 8؟", opts: ["الموضع 7","الموضع 8","الموضع 1","الموضع 9"], a: 0, ex: "المواضع تبدأ من الصفر فتشغل سلسلة من 8 حروف المواضع من 0 إلى 7." },
    { id: "algo-008", subjectId: "260210030702", difficulty: "medium", topic: "crypto", q: "على ماذا يعتمد أمان التشفير في الأنظمة الحديثة؟", opts: ["سرية المفتاح","سرية الخوارزمية","سرعة الجهاز","طول الرسالة"], a: 0, ex: "الخوارزميات معلنة ومعيارية، والأمان في سرية المفتاح لا في إخفاء الخوارزمية." },
  ]},
  "260210030802": { name: "مفاهيم نظم التشغيل", questions: [
    { id: "osys-001", subjectId: "260210030802", difficulty: "easy", topic: "intro", q: "ما التعريف الأدق لنظام التشغيل؟", opts: ["برنامج يستخدم الموارد المادية للحاسب لتقديم الدعم اللازم لتشغيل برامج أخرى","لغة برمجة عالية المستوى لبناء التطبيقات","جهاز يدير تغذية الكهرباء عن المكونات","ملف نصي يشرح طريقة استخدام الحاسب"], a: 0, ex: "نظام التشغيل برنامج يستخدم موارد الحاسب المادية ليهيئ بيئة تشغيل البرامج ويدير الموارد ويفرض التفاعل المنضبط." },
    { id: "osys-002", subjectId: "260210030802", difficulty: "easy", topic: "tasks", q: "ما دور مشغّل الجهاز (Device Driver)؟", opts: ["ترجمة أوامر النظام العامة إلى أوامر يفهمها جهاز بعينه","تصميم واجهة المستخدم الرسومية","جدولة العمليات على المعالج","ضغط الملفات قبل تخزينها"], a: 0, ex: "المشغل برنامج داخل النواة يترجم الأوامر العامة الموجهة للجهاز إلى أوامر خاصة بطراز ذلك الجهاز." },
    { id: "osys-003", subjectId: "260210030802", difficulty: "easy", topic: "virtualization", q: "ما وظيفة اللقطة (Snapshot) في إدارة الأجهزة الافتراضية؟", opts: ["حفظ حالة الجهاز — إعدادات وأقراص وربما ذاكرة — للرجوع إليها لاحقًا","إيقاف المضيف مؤقتًا لتسريع الضيف","نسخ ملفات المضيف إلى الشبكة تلقائيًا","تشفير قرص الجهاز الافتراضي"], a: 0, ex: "اللقطة نسخة من حالة الجهاز تعاد عند الحاجة، فتفيد قبل تجربة إعدادات أو تحديثات خطرة ثم التراجع عنها." },
    { id: "osys-004", subjectId: "260210030802", difficulty: "easy", topic: "processes", q: "ما المقصود بالعملية (Process)؟", opts: ["برنامج قيد التنفيذ مع موارده","برنامج مخزن على القرص فقط","ملف إعدادات للنظام","جهاز طرفي متصل بالحاسب"], a: 0, ex: "العملية برنامج قيد التنفيذ وتشمل كوده وذاكرته وسجلاته وحالته؛ البرنامج المخزن ساكن ويصير عملية عند تشغيله." },
    { id: "osys-005", subjectId: "260210030802", difficulty: "medium", topic: "scheduling", q: "أي خوارزمية جدولة تنفذ العملية الأقصر أولًا لتقليل متوسطي الانتظار والدوران؟", opts: ["الأقصر أولًا (SJF)","الأولى بالورود (FCFS)","التناوب الدائري (Round Robin)","لا شيء منها"], a: 0, ex: "SJF تقدم صاحبة الوقت الأقل فلا تترك القصيرة خلف الطويلة، لكنها تقدر الأزمنة من سلوك العمليات السابق." },
    { id: "osys-006", subjectId: "260210030802", difficulty: "medium", topic: "memory", q: "ما وظيفة جدول الصفحات في الذاكرة الافتراضية؟", opts: ["ربط رقم كل صفحة برقم إطارها وبتمييز ما إذا كانت مقيمة أو على القرص","تمزيق الملفات إلى كتل على القرص","ترتيب العمليات في طابور الجاهزين","ضبط سرعة المعالج أثناء التبديل السياقي"], a: 0, ex: "الجدول يربط الصفحة بإطارها ويحمل بت الصلاحية؛ وإن كانت الصفحة على القرص وقع خطأ الصفحة وجُلبت إلى إطار ثم حُدّث الجدول." },
    { id: "osys-007", subjectId: "260210030802", difficulty: "medium", topic: "filesystems", q: "أين يُحفظ اسم الملف في نظام الملفات؟", opts: ["في المجلد، بينما يحفظ الحرز الصفات والبيانات الوصفية","داخل الحرز إلى جانب الصلاحيات","في كتلة البيانات الأولى من الملف","لا يُحفظ الاسم إطلاقًا بعد الإنشاء"], a: 0, ex: "المجلد جدول يربط الأسماء بأرقام الأحراز، والحرز يحمل الصفات — النوع والصلاحيات والمالك والحجم والتواريخ — دون الاسم." },
    { id: "osys-008", subjectId: "260210030802", difficulty: "easy", topic: "linux", q: "ما الأمر الذي يكشف موقعك الحالي في شجرة المجلدات؟", opts: ["pwd","ls","cd","man"], a: 0, ex: "pwd يعرض المسار الحالي؛ وهو أول خطوة آمنة قبل التنقل أو الحذف في سطر أوامر Linux." },
  ]},
  "260210030902": { name: "السياسات والتشريعات والأخلاقيات والالتزام بها", questions: [
    { id: "pol-001", subjectId: "260210030902", difficulty: "easy", topic: "policy", q: "ما التعريف الأدق للسياسة الأمنية؟", opts: ["وثيقة توفر متطلبات الأمن السيبراني المبنية على أفضل الممارسات وتوثق التزام الجهة بها لتقليل المخاطر","برنامج مضاد للفيروسات يُوزَّع على أجهزة العاملين","تقرير مالي يرصد مخاطر التشغيل والأرباح","جهاز جدار حماية متطور يحمي الشبكة الداخلية"], a: 0, ex: "السياسة وثيقة توفر المتطلبات المبنية على أفضل الممارسات والمعايير وتوثق التزام الجهة بها لتقليل مخاطرها وحمايتها من التهديدات — لا أداة تقنية بعينها." },
    { id: "pol-005", subjectId: "260210030902", difficulty: "easy", topic: "laws", q: "ما العناصر الأربعة المتسلسلة للتحكم في الوصول؟", opts: ["تحديد الهوية ثم المصادقة ثم التصريح بالوصول ثم المحاسبة","المصادقة ثم التشفير ثم النسخ الاحتياطي ثم المراجعة","جدار الحماية ثم كشف التسلل ثم الحماية ثم الاستجابة","كلمة المرور ثم البصمة ثم الرمز السري ثم الشهادة"], a: 0, ex: "يبدأ المسار بتحديد الهوية فالمصادقة فالتصريح بالوصول، ثم تأتي المحاسبة التي تتتبع الأفعال وتسندها وتمنع إنكارها وتدعم كشف المخالفات." },
    { id: "pol-009", subjectId: "260210030902", difficulty: "easy", topic: "ethics", q: "من يشمل لفظ العاملين في الجهة وفق الضوابط الأساسية للأمن السيبراني؟", opts: ["كل من يعمل في الجهة أياً كانت صفته التعاقدية","الموظفون الرسميون على العقود الدائمة فقط","العاملون في إدارة الأمن السيبراني وحدهم","من أمضى سنة خدمة كاملة على الأقل"], a: 0, ex: "لا تعفي الصفة التعاقدية من الالتزام؛ فالعاملون يشملون الموظفين والمتعاقدين أياً كانت صفة العلاقة التعاقدية." },
    { id: "pol-013", subjectId: "260210030902", difficulty: "easy", topic: "compliance", q: "ما المقصود بمخاطر عدم الالتزام (Compliance Risk)؟", opts: ["احتمال تطبيق عقوبات نظامية أو خسائر مالية جسيمة أو الإضرار بالسمعة نتيجة مخالفة الأنظمة والتعليمات","احتمال تعطل الشبكة بسبب خلل تقني في العتاد","ارتفاع تكاليف تراخيص البرمجيات السحابية","تباطؤ اتصال الفروع البعيدة بالمركز الرئيسي"], a: 0, ex: "مخاطر عدم الالتزام تطبيق عقوبات نظامية أو خسائر مالية جسيمة أو ضرر بالسمعة؛ ويعد التصرف المضر بالسمعة خطرًا حتى دون مخالفة نصية." },
    { id: "pol-017", subjectId: "260210030902", difficulty: "easy", topic: "risk", q: "ما الفرق بين الثغرة والتهديد؟", opts: ["الثغرة ضعف قائم في الأصول أو الضوابط أو الإجراءات، والتهديد ظرف أو حدث يؤثر سلبًا باستغلال ذلك الضعف","الثغرة برنامج خبيث والتهديد خلل مادي في الأجهزة","كلاهما اسمان لشيء واحد لا فرق بينهما","الثغرة تخص الشبكات والتهديد يخص الأفراد فقط"], a: 0, ex: "الثغرة ضعف قائم في الجهة كنسيان تحديث أو صلاحية واسعة، والتهديد ظرف أو حدث يستغل الضعف ويؤثر سلبًا؛ والخلط بينهما خطأ شائع." },
    { id: "pol-021", subjectId: "260210030902", difficulty: "easy", topic: "awareness", q: "على أي شرطين تقوم الثقافة الأمنية في الجهة؟", opts: ["قدرة العاملين على أداء أدوارهم الأمنية واستعدادهم لأدائها","عدد الدورات التدريبية المنفذة سنويًا","حجم الميزانية المخصصة للتوعية","وجود إدارة مستقلة للأمن السيبراني"], a: 0, ex: "القدرة وحدها لا تكفي؛ فالقدرة تُكتسب بالتدريب والمعرفة، والاستعداد يظهر في القبول بالبرنامج ودعمه على كل المستويات حتى يتحول التدريب إلى سلوك." },
  ]},
  "260210031002": { name: "مكونات أنظمة تقنية المعلومات", questions: [
    { id: "itc-001", subjectId: "260210031002", difficulty: "easy", topic: "systems", q: "ما المكونات الخمسة لنظام المعلومات؟", opts: ["العتاد والبرمجيات والبيانات والإجراءات والأفراد", "الخوادم والشبكات ومحطات العمل فقط", "المعالج والذاكرة ولوحة المفاتيح والشاشة", "أنظمة التشغيل والتطبيقات وقواعد البيانات"], a: 0, ex: "نظام المعلومات أوسع من الحاسب: عتاد وبرمجيات وبيانات وإجراءات وأفراد يتكاملون معًا، وإغفال أي مكون يخل بتوازن النظام." },
    { id: "itc-005", subjectId: "260210031002", difficulty: "easy", topic: "components", q: "ما وظيفة وحدة المعالجة المركزية في الحاسب؟", opts: ["تنفيذ التعليمات وإجراء العمليات الحسابية والمنطقية", "تخزين الملفات بشكل دائم بعد إطفاء الجهاز", "عرض الصور والفيديو على الشاشة", "توصيل الحاسب بشبكة الإنترنت"], a: 0, ex: "المعالج عقل الحاسب: ينفذ التعليمات ويعالج البيانات عبر وحدة الحساب والمنطق ووحدة السيطرة والمسجلات، ويوجه بقية المكونات." },
    { id: "itc-009", subjectId: "260210031002", difficulty: "easy", topic: "cloud", q: "ما التعريف الأدق للحوسبة السحابية؟", opts: ["تقديم خدمات الحوسبة — خوادم وتخزينًا وبرمجيات — عبر الشبكة عند الطلب", "امتلاك المنظمة مراكز بيانات محلية خاصة بها", "تخزين الملفات على القرص الصلب الشخصي", "شبكة داخلية تربط أجهزة مكتب واحد"], a: 0, ex: "السحابة نموذج لتقديم موارد الحوسبة عبر الشبكة عند الطلب، فتصير الخدمة كالمرافق العامة بدل بناء بنية تحتية محلية مملوكة." },
    { id: "itc-013", subjectId: "260210031002", difficulty: "easy", topic: "security", q: "ما الأركان الثلاثة لأمن المعلومات (ثلاثية CIA)؟", opts: ["السرية والسلامة والتوافر", "السرعة والدقة والسعة", "التشفير والضغط والنسخ", "المصادقة والتخويل والتسجيل"], a: 0, ex: "السرية حماية المعلومات من الإفصاح لغير المصرح لهم، والسلامة حفظها من التغيير غير المشروع، والتوافر إتاحتها حين الحاجة." },
    { id: "itc-017", subjectId: "260210031002", difficulty: "easy", topic: "databases", q: "ما وظيفة نظام إدارة قواعد البيانات DBMS؟", opts: ["برمجيات تدير تخزين البيانات واسترجاعها والتحكم في الوصول إليها", "لغة برمجة لبناء واجهات المستخدم", "جهاز لتخزين النسخ الاحتياطية", "بروتوكول لنقل الملفات بين الشبكات"], a: 0, ex: "DBMS طبقة برمجية تنظم التخزين والاستعلام والتحديث وتفرض القيود والصلاحيات، فتفصل المستخدم عن تفاصيل الملفات الفعلية." },
    { id: "itc-021", subjectId: "260210031002", difficulty: "easy", topic: "netsec", q: "ما التصيد الاحتيالي؟", opts: ["رسائل خادعة تنتحل جهة موثوقة لدفع الضحية إلى كشف بياناتها", "برنامج يقوي كلمات المرور ويديرها", "سياسة تشدد إعدادات الشبكة الداخلية", "نسخة احتياطية من البيانات الحساسة"], a: 0, ex: "التصيد خداع بشري: رسالة أو رابط ينتحل جهة موثوقة ليسلّم الضحية بياناته طوعًا؛ ولهذا يُدرَّب المستخدم لأنه خط الدفاع الأول." },
    { id: "itc-025", subjectId: "260210031002", difficulty: "easy", topic: "analysis", q: "ما دور محلل الأنظمة؟", opts: ["حلقة وصل بين تقنية المعلومات وإدارات العمل يدرس الأنظمة ويحدد التحسينات", "مبرمج مسؤول عن كتابة الشيفرة كاملة", "مدقق مالي يراجع حسابات المشروع", "فني يركب الشبكات والأجهزة"], a: 0, ex: "المحلل جسر بين الجانب التقني واحتياجات العمل: يفهم المشكلة ويجمع المتطلبات ويحلل العمليات ويقترح الحلول ويوثقها." },
  ]},
  "260210031102": { name: "مبادئ التصميم في الأمن السيبراني", questions: [
    { id: "des-001", subjectId: "260210031102", difficulty: "easy", topic: "intro", q: "ما التعريف الأدق للتصميم الأمني؟", opts: ["بناء الحماية في بنية النظام وقراراته المعمارية منذ المراحل الأولى لا إلحاقها بعد اكتمال البناء","تركيب أقوى برامج الحماية على النظام بعد تشغيله","إخفاء أسماء الأنظمة وواجهاتها عن المستخدمين","تشفير الملفات المهمة عند الحاجة فقط"], a: 0, ex: "التصميم الأمني قرار هندسي يُبنى مع البنية نفسها: كل قرار معماري إما يضيّق الخسائر المحتملة أو يوسّعها، وإلحاق الأمن لاحقًا يجعله ترقيعًا مكلفًا." },
    { id: "des-005", subjectId: "260210031102", difficulty: "easy", topic: "components", q: "لماذا يوصف الأمن بأنه خاصية ناشئة (Emergent Property)؟", opts: ["لأنه ينتج عن تفاعل المكونات عبر هندسة منضبطة لا عن أي جزء منفرد","لأنه يظهر تلقائيًا بمجرد تركيب المكونات","لأنه يُقاس بعدد المكونات المثبتة في النظام","لأنه يزول عند كل إعادة تشغيل للنظام"], a: 0, ex: "جودة الأجزاء وحدها لا تنتج أمنًا؛ فالأمن خاصية ناشئة من العلاقة بين المستخدمين والهويات والقرارات والموارد عبر هندسة تعكس احتياجات الحماية." },
    { id: "des-009", subjectId: "260210031102", difficulty: "easy", topic: "threats", q: "من أي عناصر يبدأ تفكيك الخسارة في تحليل الخطر؟", opts: ["الأصل الذي يستحق الحماية والتهديد والثغرة والأثر المترتب","الخادم والشبكة والمستخدم ونظام التشغيل","الميزانية والجدول الزمني وحجم الفريق","الشيفرة والاختبارات ووثائق التسليم فقط"], a: 0, ex: "اجتماع تهديد بثغرة على أصل فينتج أثر محتمل؛ وبهذا التفكيك تُبنى القرارات على تصور واضح لا على انطباع عام." },
    { id: "des-013", subjectId: "260210031102", difficulty: "easy", topic: "resilience", q: "ما أقوى بدائل معالجة الخسارة في ترتيب القوة؟", opts: ["القضاء على الخسارة أصلًا بإزالة الوظيفة الخطرة أو البيانات غير اللازمة","تركيب جدار حماية إضافي أمام النظام","زيادة عدد الخوادم للتوزيع","توثيق الحادثة بعد وقوعها وتحسين التقارير"], a: 0, ex: "الترتيب يبدأ بالقضاء على الخسارة حين يمكن — فما لا يوجد لا يُخترق — ثم التقليل، ثم الضوابط الهندسية، فالرؤية والمراقبة، فالإجراءات والتدريب." },
    { id: "des-017", subjectId: "260210031102", difficulty: "easy", topic: "software", q: "ما الغاية من مراجعة التصميم الأمني في دورة تطوير البرمجيات؟", opts: ["تقييم البدائل المعمارية قبل التنفيذ واختيار الأكثر عزلًا للمكونات الحساسة","فحص تنسيق الشيفرة وإزالة التعليقات القديمة","قياس سرعة التطبيق قبل إطلاقه للعامة","تدقيق فواتير مزود الخدمة السحابية"], a: 0, ex: "المراجعة تسبق التنفيذ: تُقارن البدائل ويُختار ما يفصل المكونات الحساسة — مثل فصل حساب قاعدة البيانات عن واجهة العرض — قبل أن تُكتب الشيفرة." },
    { id: "des-021", subjectId: "260210031102", difficulty: "medium", topic: "testing", q: "ما الذي يجيب عنه الاختبار الأمني ولا يجيب عنه الاختبار الوظيفي؟", opts: ["كيف يفشل النظام حين يُقصد به السوء بدل الاقتصار على تحقق الوظائف","هل ينفذ النظام كل الوظائف الموعودة","كم يستغرق البناء والاختبار قبل الإطلاق","ما تكلفة تشغيل النظام شهريًا"], a: 0, ex: "الوظيفي يسأل: هل يفعل النظام ما وُعد به؟ والأمني يسأل: كيف يفشل أمام قصد السوء؟ ولا يكفي أحدهما عن الآخر." },
    { id: "des-025", subjectId: "260210031102", difficulty: "easy", topic: "modern", q: "ما جوهر مبدأ المسؤولية المشتركة في السحابة؟", opts: ["توزيع الواجبات بحسب نموذج الخدمة مع بقاء مسؤولية البيانات والهويات والإعدادات على العميل","إعفاء العميل من كل واجب بمجرد الاشتراك في الخدمة","بقاء كل المسؤولية على المزود في جميع النماذج","انتفاء الحاجة إلى الضوابط الأمنية عند استخدام السحابة"], a: 0, ex: "نموذج الخدمة يحدد أين تنتهي مسؤولية المزود وأين تبدأ مسؤولية العميل؛ ويبقى العميل مسؤولًا عن بياناته وهوياته وإعداداته في كل الأحوال." },
  ]}
};

var QUIZZES = {};

async function loadQuizData() {
  let data = null;
  try {
    data = await fetchJsonWithRetry("./data/quizzes.json");
  } catch (e) {
    console.warn("Quiz data unavailable — falling back to embedded bank:", e.message);
  }

  /* Empty or failed fetch resolves to the embedded bank seamlessly. */
  const cleaned = sanitizeQuizPayload(data);
  if (Object.keys(cleaned).length > 0) {
    Object.assign(QUIZZES, cleaned);
  } else {
    Object.assign(QUIZZES, MOCK_QUIZZES);
    console.info("Quizzes: using embedded fallback bank.");
  }
  /* MODULE 98 · merge the real past-quiz bank (بنك الفترات) after the
     main banks so its per-subject cards join the same quiz hub grid. */
  await loadQuizBankData();
  if (app) renderPicks();
  /* The bank just arrived — subject keys in QUIZZES are now resolvable,
     so notify listeners (e.g. HeroContinue) to re-evaluate saved progress. */
  document.dispatchEvent(new CustomEvent("nova:progress-changed"));
}

 
/* ============================================================
   MODULE 13 · QuizEngine — state, persistence & countdown
   ------------------------------------------------------------
   Persistence layer: IndexedDB (via IdbStore) with a write-
   through in-memory cache. Legacy localStorage data migrates
   automatically via IdbStore.migrateFromLocalStorage().
   ============================================================ */
const TIME_PER_Q = 30; // seconds per question in timed mode
let timedMode = Store.get("timed", false) === true;

/** In-memory mirror of the persisted store (deep-cloned on read). */
var quizCache = { results: {}, progress: {} };
/** Set to true after IdbStore loads existing data. */
var cacheReady = false;

let curKey = null;
let curIndex = 0;
let score = 0;
let total = 0;
let answered = false;
/** Per-question outcomes of the current run: "good" | "bad" | "timeout". */
let outcomes = [];

/**
 * Question order for the active run. null = natural order (all
 * questions). Array of question-indexes = filtered run (retry-wrong).
 * @type {number[]|null}
 */
var questionOrder = null;

/** Which view the quiz surface shows ("pick" | "question" | "result"). */
var quizView = "pick";
/** Last computed result payload, kept for locale re-renders. */
var lastResult = null;

/** @type {number|null} */ var timerId = null;
/** @type {number} */ var deadline = 0;
/** Exam-level deadline (ms timestamp) in timed mode. @type {number} */
var examDeadline = 0;
/** Guard flag to prevent double-click on "Show Result" button. @type {boolean} */
var isShowingResult = false;

/**
 * Read a deep clone of the quiz store from the in-memory cache.
 * @returns {{results:Object,progress:Object}} Store snapshot.
 */
function readStore() {
  return JSON.parse(JSON.stringify(quizCache));
}

/* Expose the shared quiz helpers for the top-level modules (MODULE
   43/47/48) that live outside this IIFE's scope. QUIZZES is exposed by
   reference: loadQuizData() mutates the same object, so the alias stays
   in sync. */
window.readStore = readStore;
window.QUIZZES = QUIZZES;
window.startQuiz = startQuiz;

/* Live accessor for the AI assistant (assistant.js reads window.quizCache
   for progress-aware answers). A getter is required because quizCache is
   re-assigned on hydration/write — a plain alias would go stale and the
   assistant would keep answering from an empty store. */
try {
  Object.defineProperty(window, "quizCache", { get: () => quizCache, configurable: true });
} catch (e) { /* older engines: assistant falls back to {} as before */ }

/**
 * Persist the quiz store: update cache immediately, then
 * fire-and-forget an async IndexedDB write.
 * @param {{results?:object,progress?:object}} d Payload.
 * @returns {void}
 */
function writeStore(d) {
  quizCache = JSON.parse(JSON.stringify(d));
  /* Fire-and-forget write; swallow rejections so an IndexedDB
     open/tx error (e.g. storage blocked, versioned DB) can never
     surface as an unhandled promise rejection in the console. */
  IdbStore.set("quiz", d).catch(() => {});
  /* Notify live modules (e.g. HeroContinue) so they refresh the moment
     the store changes. Additive — no behavior change. */
  document.dispatchEvent(new CustomEvent("nova:progress-changed"));
}

/**
 * Remove the saved resume-point for one subject.
 * @param {string} key Subject key.
 * @returns {void}
 */
function clearProgress(key) {
  const d = readStore();
  if (d.progress) { delete d.progress[key]; writeStore(d); }
}

/**
 * Save the current position so reloads can resume mid-quiz.
 * @param {number} nextIdx Next unanswered index.
 * @returns {void}
 */
function saveProgress(nextIdx) {
  if (nextIdx >= total) return;
  /* retry-wrong runs are transient subsets over the bank; a resume
     point tied to questionOrder would be ambiguous, so skip it. */
  if (questionOrder) return;
  const d = readStore();
  d.progress = d.progress || {};
  d.progress[curKey] = { idx: nextIdx, score, total };
  writeStore(d);
}

/** Halt any running countdown. @returns {void} */
function stopTimer() {
  if (timerId) { clearInterval(timerId); timerId = null; }
}

/**
 * Clear all transient quiz state so every subject is selectable again.
 * Persisted results are intentionally kept.
 * @returns {void}
 */
function resetEngineState() {
  stopTimer();
  questionOrder = null;
  curKey = null;
  curIndex = 0;
  score = 0;
  total = 0;
  answered = false;
  outcomes = [];
  examDeadline = 0;
  isShowingResult = false;
}

/** Start per-question countdown in timed mode. @returns {void} */
function startTimer() {
  stopTimer();
  if (!timedMode) return;
  /* Per-question override (q.t seconds), falling back to TIME_PER_Q. */
  var qSecs = Number(current().t) > 0 ? Number(current().t) : TIME_PER_Q;
  deadline = Date.now() + qSecs * 1000;
  /* Set the overall exam deadline on the first question of an exam run. */
  if (!examDeadline || curIndex === 0) {
    examDeadline = Date.now() + total * TIME_PER_Q * 1000;
  }

  const tick = () => {
    var remain = Math.max(0, deadline - Date.now());
    var frac = remain / (qSecs * 1000);
    var fill = app.querySelector(".q-timer-fill");
    if (fill) fill.style.width = (frac * 100).toFixed(1) + "%";
    var bar = app.querySelector(".q-timer");
    if (bar) bar.classList.toggle("is-low", frac <= 0.25);
    var tEl = app.querySelector("#qTimerText");
    if (tEl) tEl.textContent = "\u23F1 " + Math.ceil(remain / 1000) + " \u062B";
    /* Exam timer display. */
    var examEl = app.querySelector("#qExamTimer");
    if (examEl) {
      var exR = Math.max(0, examDeadline - Date.now());
      var em = Math.floor(exR / 60000);
      var es = Math.floor((exR % 60000) / 1000);
      examEl.textContent = (em < 10 ? "0" : "") + em + ":" + (es < 10 ? "0" : "") + es;
      examEl.classList.toggle("is-low", exR <= 30000);
    }
    if (remain <= 0) timeoutAnswer();
    /* Exam time expired — auto-submit. */
    else if (Date.now() >= examDeadline) showResult();
  };
  tick();
  timerId = setInterval(tick, 150);
}

/**
 * Escape HTML-significant characters (quiz alias).
 * @param {string} s Raw text.
 * @returns {string} Escaped text.
 */
function esc(s) { return escHtml(s); }

/* MODULE 13a · MissedBank — localStorage persistence for missed questions.
   Contract: a subject card in the quiz picker ALWAYS opens the full bank;
   a missed-only replay starts only from an explicit control (the «راجع
   أخطاءك» button under the card, the result screen's retry button, or the
   Progress hub's retry action). */
const MissedBank = {
  KEY: "missed",
  read() {
    try {
      const v = Store.get(MissedBank.KEY, null);
      return (v && typeof v === "object" && !Array.isArray(v)) ? v : {};
    } catch { return {}; }
  },
  write(obj) { try { Store.set(MissedBank.KEY, obj); } catch {} },
  idOf(k, i) { return k + ":" + i; },
  add(k, i) { const l = MissedBank.read(); l[MissedBank.idOf(k, i)] = Date.now(); MissedBank.write(l); },
  remove(k, i) { const l = MissedBank.read(); const id = MissedBank.idOf(k, i); if (id in l) { delete l[id]; MissedBank.write(l); } },
  forSubject(k) { const l = MissedBank.read(); const p = k + ":"; return Object.keys(l).filter((id) => id.indexOf(p) === 0).map((id) => parseInt(id.slice(p.length), 10)).filter((qi) => Number.isInteger(qi) && qi >= 0).sort((a, b) => a - b); },
  countForSubject(k) { return MissedBank.forSubject(k).length; },
  prune() { const l = MissedBank.read(); const ks = Object.keys(l); if (!ks.length) return; let ch = false; ks.forEach((id) => { const ps = id.split(":"); const idx = parseInt(ps[ps.length - 1], 10); const k = ps.slice(0, -1).join(":"); const b = QUIZZES[k]; if (!b || !b.questions || idx >= b.questions.length) { delete l[id]; ch = true; } }); if (ch) MissedBank.write(l); }
};

/** Quiz UI mount point. @type {HTMLElement|null} */
const app = $id("quizApp"); 
 
/**
 * Render the subject picker with badges, mode switch and clear action.
 * @returns {void}
 */
function renderPicks() {
  quizView = "pick";
  const data = readStore();
  const results = data.results || {};
  const progress = data.progress || {};
  const keys = Object.keys(QUIZZES);
  /* MODULE 99 · bank:<id> keys drive the dedicated بنك الفترات hub below
     the quiz grid — they no longer appear as subject cards in the grid. */
  const subjectKeys = keys.filter((k) => k.indexOf("bank:") !== 0);
  const hasData = Object.keys(results).length > 0 || Object.keys(progress).length > 0;
  const noBank = subjectKeys.length === 0;
  const curLang = Lang.current || "ar";
  const completedCount = subjectKeys.filter((k) => results[k]).length;
  const inProgressCount = subjectKeys.filter((k) => progress[k] && progress[k].idx > 0 && progress[k].idx < progress[k].total).length;
  const reviewCount = subjectKeys.filter((k) => MissedBank.countForSubject(k) > 0).length;
  const overallPct = subjectKeys.length ? Math.round(subjectKeys.reduce((sum, k) => sum + (results[k] && typeof results[k].pct === "number" ? results[k].pct : 0), 0) / subjectKeys.length) : 0;
  const orderedKeys = subjectKeys.slice().sort((a, b) => {
    const rank = (k) => {
      const saved = progress[k];
      if (saved && saved.idx > 0 && saved.idx < saved.total) return 0;
      if (!results[k]) return 1;
      if (MissedBank.countForSubject(k) > 0) return 2;
      return 3;
    };
    return rank(a) - rank(b);
  });
  const recommended = orderedKeys[0];
  const recommendedBank = recommended ? QUIZZES[recommended] : null;

  const cards = orderedKeys.map((k, index) => {
    const bank = QUIZZES[k] || {};
    const best = results[k];
    const saved = progress[k];
    const resumable = saved && saved.idx > 0 && saved.idx < saved.total;
    const missedCount = MissedBank.countForSubject(k);
    const total = Array.isArray(bank.questions) ? bank.questions.length : 0;
    const status = resumable
      ? { ar: "قيد التفاعل", en: "In progress", cls: "is-progress" }
      : best
        ? { ar: "آخر نتيجة", en: "Last result", cls: "is-complete" }
        : { ar: "لم تبدأ", en: "Not started", cls: "is-new" };
    const statusText = curLang === "en" ? status.en : status.ar;
    const bestText = best ? (curLang === "en" ? "Best" : "أفضل نتيجة") + " " + best.pct + "%" : (curLang === "en" ? "No result yet" : "لم تبدأ بعد");
    const action = resumable
      ? (curLang === "en" ? "Resume quiz" : "استكمال الاختبار")
      : best
        ? (curLang === "en" ? "Retake quiz" : "إعادة الاختبار")
        : (curLang === "en" ? "Start quiz" : "ابدأ الاختبار");
    const questionsText = curLang === "en" ? total + " questions" : total + " أسئلة";
    const missedText = curLang === "en" ? missedCount + " to review" : missedCount + " للمراجعة";
    const reviewText = curLang === "en" ? "Review missed answers (" + missedCount + ")" : "راجع أخطاءك (" + missedCount + ")";
    /* BUGFIX (quiz "1 من 1" report): the subject card ALWAYS launches the
       FULL bank (or resumes it). Previously a single saved entry in
       MissedBank hijacked this click into a missed-only replay, so a card
       advertising 32 questions opened a "السؤال 1 من 1" run. Missed review
       moved to the explicit control rendered below the card. */
    const card = `<button type="button" class="q-pick q-subject-card ${status.cls}" data-sub="${esc(k)}"${resumable ? ' data-resume="1"' : ""}>
      <span class="q-subject-card-top"><span class="q-subject-number">${String(index + 1).padStart(2, "0")}</span><span class="q-subject-status">${esc(statusText)}</span></span>
      <span class="q-subject-card-title">${esc(bank.name || k)}</span>
      <span class="q-subject-card-meta"><span>${esc(questionsText)}</span><span class="q-card-dot">•</span><span>${esc(bestText)}</span></span>
      ${missedCount ? `<span class="q-subject-missed">${esc(missedText)}</span>` : ""}
      <span class="q-subject-action">${esc(action)} <b aria-hidden="true">←</b></span>
    </button>`;
    /* MODULE 99 · reference banks moved OUT of this grid into the
       dedicated بنك الفترات hub (renderBankHub below). A FULL MCQ bank
       still gets a sibling "question & answer sheet" button on its card
       (its entries open the same revision sheet). */
    const isBankKey = k.indexOf("bank:") === 0;
    const sheetBtn = isBankKey
      ? `<button type="button" class="q-subject-review q-bank-sheet" data-sheet-sub="${esc(k)}">${curLang === "en" ? "Question & answer sheet (" + total + ")" : "ورقة الأسئلة والإجابات (" + total + ")"}</button>`
      : "";
    /* Missed review stays one tap away — but as an EXPLICIT sibling control
       (nested buttons are invalid HTML, hence the slot wrapper). */
    if (missedCount || sheetBtn) {
      return `<div class="q-pick-slot">${card}${missedCount ? `<button type="button" class="q-subject-review" data-review-sub="${esc(k)}">${esc(reviewText)}</button>` : ""}${sheetBtn}</div>`;
    }
    return card;
  }).join("");

  const modeRow = noBank
    ? ""
    : `<div class="q-dashboard-mode">
      <div class="q-dashboard-mode-head"><div><span class="q-kicker">${curLang === "en" ? "Choose your mode" : "اختر طريقة الاختبار"}</span><strong>${curLang === "en" ? "How do you want to test yourself?" : "كيف تريد أن تختبر نفسك؟"}</strong></div><span class="q-mode-orbit" aria-hidden="true">✦</span></div>
      <div class="q-mode-selector" role="group" aria-label="${esc(Lang.qt("modePractice"))}">
        <button type="button" class="q-mode-btn${timedMode ? "" : " is-active"}" data-mode="practice" aria-pressed="${timedMode ? "false" : "true"}"><b>${esc(Lang.qt("modePractice"))}</b><small>${curLang === "en" ? "Learn with instant explanations" : "تعلّم مع شرح فوري لكل إجابة"}</small></button>
        <button type="button" class="q-mode-btn${timedMode ? " is-active" : ""}" data-mode="exam" aria-pressed="${timedMode ? "true" : "false"}"><b>${esc(Lang.qt("modeExam"))}</b><small>${curLang === "en" ? "Timed challenge, exam-style" : "تحدٍ زمني بأسلوب الامتحان"}</small></button>
      </div>
      ${hasData ? `<button type="button" class="btn btn-ghost btn-sm q-clear" id="qClear">${esc(Lang.qt("clear"))}</button>` : ""}
    </div>`;

  const insight = noBank ? "" : `<div class="q-insight-grid">
    <section class="q-progress-card" aria-label="${curLang === "en" ? "Your overall progress" : "تقدمك العام"}">
      <div class="q-progress-copy"><span class="q-kicker">${curLang === "en" ? "Your learning pulse" : "نبض تعلمك"}</span><strong>${curLang === "en" ? "Keep your momentum" : "حافظ على تقدمك"}</strong><small>${curLang === "en" ? "One focused quiz today makes you stronger." : "اختبار واحد مركّز اليوم يجعلك أقوى."}</small></div>
      <div class="q-progress-ring" style="--pct:${overallPct * 3.6}deg"><b>${overallPct}%</b><small>${curLang === "en" ? "overall" : "المتوسط"}</small></div>
    </section>
    <section class="q-stats-card"><div><b>${completedCount}</b><small>${curLang === "en" ? "completed" : "مكتملة"}</small></div><div><b>${inProgressCount}</b><small>${curLang === "en" ? "in progress" : "جارية"}</small></div><div><b>${reviewCount}</b><small>${curLang === "en" ? "to review" : "للمراجعة"}</small></div></section>
    ${recommendedBank ? `<section class="q-recommended-card"><span class="q-kicker">${curLang === "en" ? "Recommended next" : "الاختبار المقترح"}</span><strong>${esc(recommendedBank.name)}</strong><small>${curLang === "en" ? "Start here and make this subject your next win." : "ابدأ من هنا وحوّل المادة إلى إنجازك التالي."}</small><button type="button" class="btn btn-primary btn-sm" data-sub="${esc(recommended)}"${progress[recommended] && progress[recommended].idx > 0 && progress[recommended].idx < progress[recommended].total ? ' data-resume="1"' : ""}>${curLang === "en" ? "Start recommended" : "ابدأ الاختبار المقترح"} <span aria-hidden="true">←</span></button></section>` : ""}
  </div>`;

  const picksHtml = noBank
    ? `<div class="q-data-error" role="alert"><p>${esc(Lang.qt("dataError"))}</p><button type="button" class="btn btn-sm btn-primary" id="qRetry">${esc(Lang.qt("retry"))}</button></div>`
    : `<div class="q-dashboard"><div class="q-dashboard-head"><div><span class="q-kicker">${curLang === "en" ? "Your test library" : "مكتبة اختباراتك"}</span><h3>${curLang === "en" ? "Choose a subject" : "اختر المادة التي تريد اختبارها"}</h3></div><span class="q-library-count">${subjectKeys.length} ${curLang === "en" ? "subjects" : "مواد"}</span></div>${insight}<div class="q-subject-grid">${cards}</div></div>`;

  app.innerHTML = modeRow + picksHtml;
  renderBankHub();
}

/**
 * MODULE 99 · بنك الفترات — the revision lists live in ONE hub panel
 * (#bankHub), placed after the quiz picker, outside the subject grid.
 * Every past-quiz bank renders as one numbered row that opens its
 * revision sheet directly. New subjects append automatically — the
 * panel is rebuilt from QUIZZES whenever the picker repaints, so
 * future additions to data/quiz-bank.json need zero code changes.
 * @returns {void}
 */
function renderBankHub() {
  const hub = $id("bankHub");
  const list = $id("bankHubList");
  if (!hub || !list) return;
  const curLang = Lang.current || "ar";
  const bankKeys = Object.keys(QUIZZES).filter((k) => k.indexOf("bank:") === 0);
  /* No banks (missing file / empty data) → the panel simply never shows. */
  if (!bankKeys.length) {
    hub.hidden = true;
    list.innerHTML = "";
    return;
  }
  hub.hidden = false;
  list.innerHTML = bankKeys.map((k, i) => {
    const bank = QUIZZES[k] || {};
    const refCount = Array.isArray(bank.refs) ? bank.refs.length : 0;
    const qTotal = Array.isArray(bank.questions) ? bank.questions.length : 0;
    const itemCount = refCount + qTotal;
    const chip = curLang === "en" ? "Revision sheet" : "ورقة مراجعة";
    const meta = curLang === "en" ? itemCount + " Q&A items" : itemCount + " سؤالاً وجوابًا";
    const finals = curLang === "en" ? "Finals revision" : "مرجع الفاينل";
    const cta = curLang === "en" ? "Open the revision sheet" : "افتح ورقة المراجعة";
    return `<button type="button" class="q-subject-card bank-row" data-sheet-sub="${esc(k)}">
      <span class="q-subject-card-top"><span class="q-subject-number">${String(i + 1).padStart(2, "0")}</span><span class="q-subject-status bank-hub-chip">${esc(chip)}</span></span>
      <span class="q-subject-card-title">${esc(bank.name || k)}</span>
      <span class="q-subject-card-meta"><span>${esc(meta)}</span><span class="q-card-dot">•</span><span>${esc(finals)}</span></span>
      <span class="q-subject-action">${esc(cta)} <b aria-hidden="true">←</b></span>
    </button>`;
  }).join("");
}

/**
 * MODULE 99 · one delegated click listener for the #bankHub panel.
 * #quizApp delegation cannot receive clicks from outside its own
 * subtree, so the hub carries its own binding (registered once — the
 * hub element itself is never replaced, only the row list repaints).
 * @returns {void}
 */
function bindBankHubDelegation() {
  const hub = $id("bankHub");
  if (!hub || hub.dataset.bankDelegated === "1") return;
  hub.dataset.bankDelegated = "1";
  hub.addEventListener("click", (e) => {
    const t = e.target;
    if (!t || !t.closest) return;
    const row = t.closest("[data-sheet-sub]");
    if (!row) return;
    renderSheet(row.getAttribute("data-sheet-sub"));
  });
}

/**
 * MODULE 98 · بنك الفترات — revision sheet: every past-quiz item with its
 * answer and explanation, revealed one item at a time through native
 * <details> (active recall: try to remember first, then check). Both
 * sources render identically: engine MCQ questions answer from opts,
 * reference items answer straight from answerText.
 * @param {string} key Bank key ("bank:<subjectId>").
 * @returns {void}
 */
function renderSheet(key) {
  const bank = QUIZZES[key];
  if (!app) return;
  if (!bank) return;
  const curLang = Lang.current || "ar";
  const items = [];
  (Array.isArray(bank.questions) ? bank.questions : []).forEach((q) => {
    items.push({
      q: q.q,
      answer: q.opts && q.opts[q.a] != null ? q.opts[q.a] : "",
      ex: typeof q.ex === "string" ? q.ex : "",
      meta: q.topic || ""
    });
  });
  (Array.isArray(bank.refs) ? bank.refs : []).forEach((r) => {
    items.push({
      q: r.q,
      answer: r.answerText,
      ex: typeof r.ex === "string" ? r.ex : "",
      meta: [r.source, r.topic].filter(Boolean).join(" · ")
    });
  });
  if (!items.length) return;
  quizView = "sheet";
  stopTimer();
  const rendered = items.map((it, i) => {
    const meta = it.meta;
    return '<details class="q-sheet-item" role="listitem"><summary>' +
      '<span class="q-sheet-qno" aria-hidden="true">' + String(i + 1).padStart(2, "0") + "</span>" +
      '<span class="q-sheet-qtext">' + esc(it.q) + '</span>' +
      '<span class="q-sheet-hint" aria-hidden="true">▾</span></summary>' +
      '<div class="q-sheet-body"><p class="q-sheet-answer"><b>' + esc(curLang === "en" ? "Answer" : "الإجابة") + ':</b> ' + esc(it.answer) + "</p>" +
      (it.ex ? '<p class="q-sheet-ex">' + esc(it.ex) + "</p>" : "") +
      (meta ? '<span class="q-sheet-meta">' + esc(curLang === "en" ? "From" : "المرجع") + ": " + esc(meta) + "</span>" : "") +
      "</div></details>";
  }).join("");
  app.innerHTML = '<div class="q-sheet">' +
    '<div class="q-sheet-top">' +
    `<button type="button" class="btn btn-ghost btn-sm" id="qSheetBack" aria-label="${esc(curLang === "en" ? "Back to test library" : "رجوع إلى مكتبة الاختبارات")}"><span aria-hidden="true">→</span> ${esc(curLang === "en" ? "Back" : "رجوع")}</button>` +
    `<h3 class="q-sheet-title">${esc(bank.name)}</h3>` +
    "</div>" +
    `<p class="q-sheet-note">${esc(curLang === "en" ? "Try to recall the answer first, then open the item to check." : "جرّب أن تتذكر الإجابة أولًا، ثم افتح السطر لتحقق.")}</p>` +
    `<div class="q-sheet-list" role="list">${rendered}</div>` +
    "</div>";
  app.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth", block: "start" });
}

/**
 * Start (or resume) a quiz for one subject.
 * @param {string} key Subject key.
 * @param {boolean=} resume Resume from saved progress when valid.
 * @returns {void}
 */
function startQuiz(key, resume = false, filter) {
  /* Guard: reject unknown keys (tampered DOM/data) instead of crashing. */
  const bank = QUIZZES[key];
  if (!bank || !Array.isArray(bank.questions) || bank.questions.length === 0) return;
  curKey = key;
  /* Retry-wrong: run only the supplied question indexes.
     The filtered run is traversed in position (curIndex) order;
     current() maps the position through questionOrder. */
  let ord;
  if (Array.isArray(filter) && filter.length) {
    ord = filter.map(Number).filter((qi) => Number.isInteger(qi) && qi >= 0 && qi < bank.questions.length);
    if (!ord.length) ord = bank.questions.map((_, i) => i);
  } else {
    ord = bank.questions.map((_, i) => i);
  }
  /* Exam mode: randomize the question order on every attempt. */
  if (timedMode && ord.length > 1) {
    for (let i = ord.length - 1; i > 0; i--) {
      const jx = Math.floor(Math.random() * (i + 1));
      const tmp = ord[i]; ord[i] = ord[jx]; ord[jx] = tmp;
    }
  }
  questionOrder = (timedMode || Array.isArray(filter)) ? ord : null;
  total = questionOrder ? questionOrder.length : bank.questions.length;
  const p = resume ? (readStore().progress || {})[key] : null;

  /* Exam runs always start fresh. */
  if (!timedMode && p && p.idx > 0 && p.idx < total && p.total === total) {
    curIndex = p.idx;
    score = p.score || 0;
    showQuestion(Lang.qt("resumed", { i: curIndex + 1, total }));
  } else {
    curIndex = 0;
    score = 0;
    outcomes = []; /* fresh run → reset the per-question breakdown */
    clearProgress(key);
    showQuestion();
  }
}

/**
 * Current question object for the active subject.
 * @returns {{q:string,ex:string,opts:string[],a:number}} Question.
 */
function current() {
  const qs = QUIZZES[curKey].questions;
  return qs[questionOrder ? questionOrder[curIndex] : curIndex];
}

/**
 * Render one question: top bar, timers, ARIA-wired options, actions.
 * @param {string=} resumeNote Optional banner shown after resuming.
 * @returns {void}
 */
function showQuestion(resumeNote) {
  quizView = "question";
  const q = current();
  answered = false;
  stopTimer();
  const pct = Math.round((curIndex / total) * 100);
  const optsHtml = q.opts
    .map((opt, i) => `<button type="button" class="q-option" data-i="${i}"><span class="q-option-key" aria-hidden="true">${i + 1}</span><span class="q-option-text">${esc(opt)}</span></button>`)
    .join("");
  const timerBar = timedMode
    ? '<div class="q-timer" role="timer" aria-label="الوقت المتبقي لهذا السؤال"><div class="q-timer-fill" style="width:100%"></div></div>'
    : "";
  const timerText = timedMode
    ? '<span class="q-timer-text" id="qTimerText" role="timer"></span>'
    : "";

  const modeBadge = `<span class="q-mode-badge ${timedMode ? "is-exam" : "is-practice"}">${esc(Lang.qt(timedMode ? "modeBadgeExam" : "modeBadgePractice"))}</span>`;
  app.innerHTML =
    '<div class="q-top-bar">' +
    `<span class="q-subject-title">${esc(QUIZZES[curKey].name)}</span>` +
    modeBadge +
    (timedMode ? '<span class="q-exam-timer" id="qExamTimer" role="timer" aria-label="الوقت المتبقي للاختبار">00:00</span>' : "") +
    `<span class="q-count">${esc(Lang.qt("count", { i: curIndex + 1, total }))}</span>` +
    `<span class="q-score">${esc(Lang.qt("score", { n: score }))}</span>` +
    timerText +
    "</div>" +
    timerBar +
    `<div class="q-progress"><div class="q-progress-fill" style="width:${pct}%"></div></div>` +
    (resumeNote ? `<p class="q-note">${esc(resumeNote)}</p>` : "") +
    `<h3 class="q-question" id="qQ" tabindex="-1">${esc(q.q)}</h3>` +
    `<div class="q-options" role="group" aria-labelledby="qQ">${optsHtml}</div>` +
    '<p class="q-feedback" id="qFeedback" role="status"></p>' +
    `<div class="q-actions"><button type="button" class="btn btn-ghost" id="qRestart">${esc(Lang.qt("restartSubject"))}</button></div>`;

  /* Move focus to the new question so keyboard and screen-reader users do not
     have to rediscover where the replaced content begins. */
  const questionHeading = app.querySelector("#qQ");
  if (questionHeading) questionHeading.focus({ preventScroll: true });

  /* Option + restart clicks are handled by the delegated listeners. */
  startTimer();
} 
 
/**
 * Grade a clicked option and finish the question.
 * @param {number} i Chosen option index.
 * @returns {void}
 */
function handleAnswer(i) {
  if (answered) return;
  answered = true;
  stopTimer();
  const q = current();
  const correct = q.a === i;
  if (correct) score++;
  /* Grading cue: a bright arpeggio on a hit, a soft low pair on a miss.
     Exam mode is silent by contract (same as the timeout cue below). */
  if (!timedMode) { try { Sfx.play(correct ? "good" : "bad"); } catch (e0) { /* audio is optional */ } }

  const opts = $$(".q-option", app);
  opts.forEach((b) => b.setAttribute("disabled", ""));
  if (opts[i]) opts[i].classList.add("is-selected");
  /* Exam mode suppresses correct/incorrect highlighting. */
  if (!timedMode) {
    opts[q.a].classList.add("is-correct");
    if (!correct) opts[i].classList.add("is-wrong");
  }
  /* Record into the missed bank. */
  const qi = questionOrder ? questionOrder[curIndex] : curIndex;
  if (correct) MissedBank.remove(curKey, qi);
  else MissedBank.add(curKey, qi);

  finishQuestion(correct, i);
}

/** Time expired: reveal the correct answer without scoring. @returns {void} */
function timeoutAnswer() {
  stopTimer();
  if (answered) return;
  answered = true;
  if (!timedMode) Sfx.play("timeout");
  const q = current();
  const opts = $$(".q-option", app);
  opts.forEach((b) => b.setAttribute("disabled", ""));
  if (!timedMode) opts[q.a].classList.add("is-correct");
  /* Record timeout into the missed bank. */
  const qi = questionOrder ? questionOrder[curIndex] : curIndex;
  MissedBank.add(curKey, qi);
  finishQuestion(null, null);
}

/**
 * Shared tail: feedback, explanation drawer, persistence, next button.
 * @param {boolean|null} correct Null when the question timed out.
 * @param {number|null} chosenIdx Chosen index (null on timeout).
 * @returns {void}
 */
function finishQuestion(correct, chosenIdx) {
  const q = current();
  const fb = app.querySelector("#qFeedback");

  /* Track this question's outcome for the result-screen breakdown. */
  outcomes.push(correct === null ? "timeout" : (correct ? "good" : "bad"));

  if (timedMode) {
    fb.className = "q-feedback is-exam";
    fb.textContent = "تم تسجيل إجابتك";
  } else if (correct === null) {
    fb.className = "q-feedback is-timeout";
    fb.textContent = Lang.qt("timeout", { ans: q.opts[q.a] });
  } else {
    fb.className = correct ? "q-feedback is-good" : "q-feedback is-bad";
    fb.textContent = correct
      ? Lang.qt("correct")
      : Lang.qt("wrong", { ans: q.opts[q.a] });
  }

  app.querySelector(".q-progress-fill").style.width =
    Math.round(((curIndex + 1) / total) * 100) + "%";
  app.querySelector(".q-score").textContent = Lang.qt("score", { n: score });
  const qCount = app.querySelector(".q-count");
  if (qCount) qCount.textContent = Lang.qt("count", { i: curIndex + 1, total });

  /* Explanation drawer — suppress during exam; auto-open on wrong/timeout answers */
  if (q.ex && !timedMode) {
    const wrongPick = chosenIdx !== null && chosenIdx !== q.a;
    const openAttr = correct === null || wrongPick ? " open" : "";
    fb.insertAdjacentHTML(
      "afterend",
      `<details class="q-explain"${openAttr}><summary>${esc(Lang.qt("explain"))}</summary><p>${esc(q.ex)}</p></details>`
    );
  }

  saveProgress(curIndex + 1);

  const isLast = curIndex + 1 >= total;
  const nextBtn = document.createElement("button");
  nextBtn.type = "button";
  nextBtn.id = "qNext";
  nextBtn.className = "btn btn-primary";
  nextBtn.textContent = isLast ? Lang.qt("showResult") : Lang.qt("next");
  /* Advance/result handled by the delegated #qNext listener. */
  app.querySelector(".q-actions").appendChild(nextBtn);
  nextBtn.focus({ preventScroll: true });
}

/**
 * Render the final score, persist the attempt (best kept), clear progress.
 * @returns {void}
 */
function showResult() {
  /* Guard: prevent double-click / re-entry once the result is rendered. */
  if (isShowingResult || quizView === "result") return;
  isShowingResult = true;
  stopTimer();
  /* Guard: a zero-length quiz cannot be scored — bail out cleanly. */
  if (!total || total <= 0) { isShowingResult = false; return; }
  /* Guard: ensure the quiz bank is still loaded. */
  if (!curKey || !QUIZZES[curKey]) { isShowingResult = false; return; }

  try {
    const pct = Math.round((score / total) * 100);

    const d = readStore();
    const prevBest = d.results && d.results[curKey] ? d.results[curKey].pct : 0;
    d.results = d.results || {};
    d.results[curKey] = {
      score,
      total,
      pct: Math.max(prevBest, pct),
      last: pct,
      date: new Date().toISOString().slice(0, 10)
    };
    if (d.progress) delete d.progress[curKey];
    writeStore(d);
    /* Genuine quiz completion — idempotent per bank (retakes never farm XP). */
    awardMotivation("quiz", curKey);

    /* Track wrong/timed-out question indices for the retry feature.
       The run position maps through questionOrder (null = natural), so
       wrongIndices always holds ORIGINAL bank question indexes — safe
       to replay via startQuiz(key, false, wrongIndices) even on a
       second retry over a filtered subset. */
    const questions = QUIZZES[curKey].questions || [];
    const ord = questionOrder || questions.map((_, i) => i);
    const wrongIndices = [];
    /* wrongList pairs each missed question's ORIGINAL bank index with its
       outcome ("bad"|"timeout") so the result screen can render a deferred
       explanation review (exam mode hides between-question explanations). */
    const wrongList = [];
    outcomes.forEach((o, i) => {
      if (o !== "good") {
        wrongIndices.push(ord[i]);
        wrongList.push({ qi: ord[i], o: o });
      }
    });

    /* Compute per-category breakdown from question cat field. */
    const catStats = {};
    ord.forEach((qi, i) => {
      const q = questions[qi];
      if (!q) return;
      const cat = q.cat || "general";
      catStats[cat] = catStats[cat] || { ok: 0, n: 0 };
      catStats[cat].n++;
      if (outcomes[i] === "good") catStats[cat].ok++;
    });

    /* Keep the payload so a locale switch can re-render this view. */
    lastResult = { key: curKey, score, total, pct, prevBest, outcomes: outcomes.slice(), wrongIndices, wrongList, catStats };
    renderResult();
  } catch (err) {
    /* Never leave the flag locked on error — allow retry. */
    isShowingResult = false;
    console.error("showResult failed:", err);
  }
}

/**
 * Render the result screen from the stored payload (pure DOM work,
 * no persistence side effects — safe to call on locale switches).
 * @returns {void}
 */
function renderResult() {
  quizView = "result";
  const { key, score: s, total: tt, pct, prevBest, outcomes: oc, wrongIndices, wrongList, catStats } = lastResult;
  const newRecord = !prevBest || pct > prevBest;
  const note =
    pct >= 80 ? Lang.qt("noteHi")
    : pct >= 60 ? Lang.qt("noteMid")
    : Lang.qt("noteLo");

  /* Answer breakdown. On a resumed session the questions answered before
     the reload have no recorded outcome — surfaced honestly as "غير محسوبة". */
  let breakdownHtml = "";
  if (Array.isArray(oc)) {
    const good = oc.filter((o) => o === "good").length;
    const bad = oc.filter((o) => o === "bad").length;
    const timedOut = oc.filter((o) => o === "timeout").length;
    const unknown = Math.max(0, tt - oc.length);
    const chip = (cls, n, label) =>
      '<span class="q-chip ' + cls + '"><b>' + n + "</b>" + esc(label) + "</span>";
    breakdownHtml =
      '<div class="q-result-stats" role="list" aria-label="' + esc(Lang.qt("resBreakdown")) + '">' +
      chip("is-good", good, Lang.qt("resGood")) +
      chip("is-bad", bad, Lang.qt("resBad")) +
      (timedOut ? chip("is-timeout", timedOut, Lang.qt("resTimeout")) : "") +
      (unknown ? chip("is-unknown", unknown, Lang.qt("resUnknown")) : "") +
      "</div>";
  }

  /* Per-category breakdown — shows strength/weakness by topic. */
  let catHtml = "";
  if (catStats && Object.keys(catStats).length > 0) {
    const curLang = Lang.current || "ar";
    /* QUIZ_CATS lives inside the MODULE 40 IIFE (declared further below) and
       is published on `window` there. Read it defensively: a missing map
       degrades to raw category keys instead of killing the result render. */
    const CATS = window.QUIZ_CATS || {};
    const catItems = Object.keys(catStats).map((cat) => {
      const st = catStats[cat];
      const catName = (CATS[cat] && (CATS[cat][curLang] || CATS[cat].ar)) || cat;
      return '<span class="q-chip"><b>' + st.ok + '/' + st.n + "</b> " + esc(catName) + "</span>";
    }).join("");
    catHtml = '<div class="q-result-stats q-cat-breakdown" role="list" aria-label="' + esc(Lang.qt("catBreakdown")) + '">' + catItems + "</div>";
  }

  /* Deferred review (exam mode): between-question explanations stay hidden
     during a timed run, so the full explanation for every missed answer is
     shown here instead. Practice mode already explains after each answer. */
  let reviewHtml = "";
  if (wrongList && wrongList.length > 0) {
    const qs = (QUIZZES[key] && QUIZZES[key].questions) || [];
    const items = wrongList.map((w) => {
      const q = qs[w.qi];
      if (!q) return "";
      const ans = q.opts && q.opts[q.a] != null ? q.opts[q.a] : "";
      const head = w.o === "timeout"
        ? esc(Lang.qt("timeout", { ans: ans }))
        : esc(Lang.qt("wrong", { ans: ans }));
      return '<li class="q-review-item"><p class="q-review-q">' + esc(q.q || "") + "</p><p>" + head + "</p>" +
        (q.ex
          ? '<details class="q-explain" open><summary>' + esc(Lang.qt("explain")) + "</summary><p>" + esc(q.ex) + "</p></details>"
          : "") +
        "</li>";
    }).join("");
    if (items) {
      reviewHtml = '<section class="q-review" aria-label="' + esc(Lang.qt("reviewTitle")) + '"><h4>' + esc(Lang.qt("reviewTitle")) + '</h4><ul class="q-review-list">' + items + "</ul></section>";
    }
  }

  /* Retry-incorrect button — only when there are wrong/timed-out answers. */
  let retryHtml = "";
  if (wrongIndices && wrongIndices.length > 0) {
    retryHtml = `<button type="button" class="btn btn-ghost" id="qRetryWrong">${esc(Lang.qt("retryWrong"))}</button>`;
  }

  /* Continue-learning link — back to the owning learning path.
     SUBJECT_TO_PATH lives inside the MODULE 40 IIFE (below) and is
     published on `window` there; resolve defensively. */
  let continueHtml = "";
  const ownerPath = (window.SUBJECT_TO_PATH || {})[key];
  if (ownerPath) {
    continueHtml = `<a href="#path/${ownerPath}" class="btn btn-primary q-continue-link">${esc(Lang.qt("continueLearn"))} →</a>`;
  }

  const subjectName = (QUIZZES[key] && QUIZZES[key].name) || key;
  app.innerHTML =
    '<div class="q-result">' +
    `<div class="q-result-score-wrap"><div class="q-result-score" role="status">${s}/${tt}</div></div>` +
    `<p class="q-result-label">${esc(Lang.qt("resultIn", { sub: subjectName }))}${timedMode ? esc(Lang.qt("timedSuffix")) : ""}</p>` +
    `<p class="q-result-note">${esc(note)}</p>` +
    breakdownHtml +
    catHtml +
    reviewHtml +
    `<p class="q-result-label">${esc(Lang.qt("bestSaved", { pct: Math.max(prevBest, pct) }))}${newRecord ? esc(Lang.qt("newRec")) : ""}</p>` +
    "</div>" +
    '<div class="q-actions">' +
    retryHtml +
    `<button type="button" class="btn btn-ghost" id="qAgain">${esc(Lang.qt("retake"))}</button>` +
    `<button type="button" class="btn btn-ghost" id="qPick">${esc(Lang.qt("pickOther"))}</button>` +
    continueHtml +
    "</div>";
  /* #qRetryWrong / #qAgain / #qPick clicks are handled by the delegated listeners. */
}

/**
 * Bind ONE delegated click/change pair on the quiz mount. Because
 * #quizApp itself is never replaced (only its innerHTML), these
 * survive every re-render — including the result screen — so the
 * retake / choose-subject buttons can never end up dead.
 * @returns {void}
 */
function bindQuizDelegation() {
  if (!app || app.dataset.qDelegated === "1") return;
  app.dataset.qDelegated = "1";

  /* ONE delegated click listener per quiz mount — every branch below
     guards on its own selector. Registering a second listener made
     each click traverse two handlers; mode toggles now live here too. */
  app.addEventListener("click", (e) => {
    const t = e.target;
    if (!t || !t.closest) return;

    const modeBtn = t.closest(".q-mode-btn");
    if (modeBtn) {
      const newMode = modeBtn.dataset.mode === "exam";
      if (newMode !== timedMode) {
        timedMode = newMode;
        Store.set("timed", timedMode);
        renderPicks();
      }
      return;
    }

    /* Explicit missed-review control rendered under a subject card — the ONLY
       picker entry that starts a filtered (missed-only) run. A stale badge
       (entries pruned/repaired meanwhile) degrades to the full bank. */
    const reviewBtn = t.closest("[data-review-sub]");
    if (reviewBtn) {
      const sub = reviewBtn.getAttribute("data-review-sub");
      const missed = MissedBank.forSubject(sub);
      startQuiz(sub, false, missed.length ? missed : null);
      return;
    }

    /* MODULE 98 · بنك الفترات — the revision sheet (question + answer
       + explanation, revealed one at a time through native <details>).
       Checked BEFORE the card picker: reference bank cards carry the
       sheet attribute on the card itself, and an empty engine bank
       must never swallow that click. */
    const sheetBtn = t.closest("[data-sheet-sub]");
    if (sheetBtn) {
      renderSheet(sheetBtn.getAttribute("data-sheet-sub"));
      return;
    }
    if (t.closest("#qSheetBack")) {
      renderPicks();
      return;
    }

    /* Subject cards + resume chips — always the FULL bank. Never hijacked by
       the missed bank: the card advertises the full question count, so it
       must open exactly that count. */
    const pick = t.closest(".q-pick");
    if (pick) {
      startQuiz(pick.dataset.sub, pick.dataset.resume === "1");
      return;
    }

    if (t.closest("#qAgain")) {
      const key = curKey;
      resetEngineState();
      startQuiz(key, false);
      return;
    }
    if (t.closest("#qPick")) {
      resetEngineState();
      renderPicks();
      app.scrollIntoView({
        behavior: prefersReducedMotion ? "auto" : "smooth",
        block: "start"
      });
      return;
    }
    if (t.closest("#qNext")) {
      if (curIndex + 1 >= total) showResult();
      else { curIndex++; showQuestion(); }
      return;
    }
    if (t.closest("#qRestart")) { startQuiz(curKey, false); return; }
    if (t.closest("#qRetry")) { loadQuizData(); return; }
    if (t.closest("#qClear")) { clearQuizData(); return; }
    if (t.closest("#qRetryWrong")) { startQuiz(curKey, false, lastResult.wrongIndices); return; }

    const opt = t.closest(".q-option");
    if (opt && !opt.hasAttribute("disabled")) {
      handleAnswer(parseInt(opt.dataset.i, 10));
    }
  });
}

/** Wipe saved quiz data and repaint the picker. @returns {Promise<void>} */
async function clearQuizData() {
  try { await IdbStore.del("quiz"); } catch {}
  quizCache = { results: {}, progress: {} };
  renderPicks();
}

/* Bootstrap the quiz UI only if its mount point exists. */
(async function bootQuiz() {
  if (!app) return;
  bindQuizDelegation();
  bindBankHubDelegation();
  try { await IdbStore.migrateFromLocalStorage(); } catch {}
  try {
    const saved = await IdbStore.get("quiz");
    if (saved && typeof saved === "object") {
      const r = (saved.results && typeof saved.results === "object") ? saved.results : {};
      const p = (saved.progress && typeof saved.progress === "object") ? saved.progress : {};
      const cleanProgress = {};
      Object.keys(p).forEach((k) => {
        const e = p[k];
        if (e && typeof e === "object"
            && typeof e.idx === "number" && e.idx >= 0
            && typeof e.total === "number" && e.total > 0
            && typeof e.score === "number" && e.score >= 0
            && e.idx < e.total) {
          cleanProgress[k] = { idx: e.idx, score: e.score, total: e.total };
        }
      });
      quizCache = { results: r, progress: cleanProgress };
    }
  } catch {}
  cacheReady = true;
  renderPicks();
  /* Saved data just hydrated into quizCache — notify listeners (e.g.
     HeroContinue) so the homepage continue-card paints on first load,
     not only after the next store write or view switch. */
  document.dispatchEvent(new CustomEvent("nova:progress-changed"));
  /* Prune only after the banks arrive: loadQuizData() is async, and
     pruning against the still-empty QUIZZES validated every saved
     missed question against "no bank" and wiped the whole store on
     each boot. Re-notify after pruning so counts re-read cleaned data. */
  loadQuizData().then(() => {
    MissedBank.prune();
    document.dispatchEvent(new CustomEvent("nova:progress-changed"));
  });

  /* Live locale switching for the picker / result screens. A question
     in progress keeps its language until the next render (by design). */
  Lang.onSwitch(() => {
    if (!app) return;
    if (quizView === "pick") renderPicks();
    else if (quizView === "result" && lastResult) renderResult();
    else if (quizView === "sheet" && curKey && QUIZZES[curKey]) renderSheet(curKey);
  });
})(); 
 
/* ============================================================
   MODULE 14 · Tools.Hash — SHA-256 generator & fingerprint
   ============================================================ */
(function initHashTool() {
  const input = $id("hashInput");
  const out = $id("hashOut");
  const fp = $id("hashFp");
  const copyBtn = $id("hashCopy");
  if (!input || !out) return;

  /**
   * Compute a SHA-256 hex digest via Web Crypto, with an FNV-1a×4
   * fallback that is ALWAYS labeled as a fallback, never shown as SHA-256.
   * @param {string} text Input text.
   * @returns {Promise<string>} Hex digest or FNV-1a×4 fallback string.
   */
  async function sha256Hex(text) {
    if (window.crypto && window.crypto.subtle && crypto.subtle.digest) {
      try {
        const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
        return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
      } catch (err) {
        console.warn("[Tools.Hash] Web Crypto SHA-256 failed:", err && err.message);
      }
    }
    // Web Crypto unavailable or failed — do NOT pretend this is SHA-256.
    return "FNV-1a×4-FALLBACK:" + fnv1a32x4(text);
  }

  /**
   * FNV-1a×4 fallback used only when Web Crypto is unavailable.
   * Returns 4 concatenated 32-bit FNV-1a fingerprints as hex.
   * This is NOT a cryptographic hash and is NOT SHA-256.
   * @param {string} text
   * @returns {string} hex fingerprint
   */
  function fnv1a32x4(text) {
    let out = "";
    for (let r = 0; r < 4; r++) {
      let h = (0x811c9dc5 ^ Math.imul(r + 1, 0x9e3779b9)) >>> 0;
      for (let i = 0; i < text.length; i++) {
        h ^= text.charCodeAt(i) + r;
        h = Math.imul(h, 0x01000193) >>> 0;
      }
      out += h.toString(16).padStart(8, "0");
    }
    return out;
  }

  /**
   * Render the hash as a colored fingerprint grid (2 hex digits/cell).
   * @param {string} hex Hex digest.
   * @returns {void}
   */
  function visualize(hex) {
    if (!fp) return;
    const cells = [];
    for (let i = 0; i < hex.length; i += 2) {
      const b = parseInt(hex.slice(i, i + 2), 16);
      if (Number.isNaN(b)) {
        cells.push(`<i style="background:#8e5f68"></i>`);
        continue;
      }
      cells.push(
        `<i style="background:hsl(${b % 360} 85% ${28 + (b % 35)}%);animation-delay:${(i / 2) * 8}ms"></i>`
      );
    }
    fp.innerHTML = cells.join("");
  }

  /**
   * Render a fallback fingerprint (FNV-1a×4) without pretending it is SHA-256.
   * @param {string} fallback Hex string with the FNV prefix removed.
   * @returns {void}
   */
  function visualizeFallback(fallback) {
    if (!fp) return;
    const hex = fallback.replace(/^FNV-1a×4-FALLBACK:/, "");
    const cells = [];
    for (let i = 0; i < hex.length; i += 2) {
      const b = parseInt(hex.slice(i, i + 2), 16);
      if (Number.isNaN(b)) {
        cells.push(`<i style="background:#8e5f68"></i>`);
        continue;
      }
      cells.push(
        `<i style="background:hsl(${b % 360} 85% ${28 + (b % 35)}%);animation-delay:${(i / 2) * 8}ms"></i>`
      );
    }
    fp.innerHTML = cells.join("");
  }

  const run = debounce(async () => {
    if (!input.value) { out.textContent = "—"; if (fp) fp.innerHTML = ""; return; }
    try {
      const hex = await sha256Hex(input.value);
      out.textContent = hex;
      if (hex.startsWith("FNV-1a×4-FALLBACK:")) {
        // Never display the FNV fallback as if it were SHA-256.
        out.classList.add("is-fallback");
        visualizeFallback(hex);
      } else {
        out.classList.remove("is-fallback");
        visualize(hex);
      }
    } catch { out.textContent = "تعذّر توليد البصمة في هذا المتصفح."; }
  }, 150);

  input.addEventListener("input", run);

  if (copyBtn) copyBtn.addEventListener("click", async () => {
    if (!out.textContent || out.textContent === "—") return;
    try {
      await navigator.clipboard.writeText(out.textContent);
      copyBtn.textContent = "تم النسخ ✓";
      setTimeout(() => { copyBtn.textContent = "نسخ البصمة"; }, 1500);
    } catch {}
  });
})(); 
 
/* ============================================================
   MODULE 15 · Tools.Caesar — Arabic/Latin shift cipher
   ============================================================ */
(function initCaesarTool() {
  const cIn = $id("cipherIn");
  const cOut = $id("cipherOut");
  const range = $id("shiftRange");
  const val = $id("shiftVal");
  if (!cIn || !cOut || !range || !val) return;

  const AR = "ابتثجحخدذرزسشصضطظعغفقكلمنهوي";
  const EN = "abcdefghijklmnopqrstuvwxyz";

  /**
   * Wrap a shifted alphabet index into [0, len), supporting negative shifts.
   * @param {number} i Shifted index.
   * @param {number} len Alphabet length.
   * @returns {number} Normalised index.
   */
  function wrapIdx(i, len) { return ((i % len) + len) % len; }

  /**
   * Shift Arabic/Latin letters by k positions; others pass through.
   * @param {string} text Source text.
   * @param {number} k Shift amount.
   * @returns {string} Transformed text.
   */
  function shiftText(text, k) {
    return [...text].map((ch) => {
      const ai = AR.indexOf(ch);
      if (ai > -1) return AR[wrapIdx(ai + k, AR.length)];
      const lower = ch.toLowerCase();
      const ei = EN.indexOf(lower);
      if (ei > -1) {
        const s = EN[wrapIdx(ei + k, 26)];
        return ch === lower ? s : s.toUpperCase();
      }
      return ch;
    }).join("");
  }

  /** Recompute output from current input and shift. @returns {void} */
  function runCipher() {
    const k = parseInt(range.value, 10);
    val.textContent = String(k);
    cOut.textContent = cIn.value ? shiftText(cIn.value, k) : "—";
  }

  cIn.addEventListener("input", runCipher);
  range.addEventListener("input", runCipher);
  runCipher();

  /* Copy-to-clipboard with transient "تم النسخ" feedback (parity with
     the hash tool; silently ignored when the clipboard is unavailable). */
  const cCopy = $id("cipherCopy");
  if (cCopy) cCopy.addEventListener("click", async () => {
    const text = cOut.textContent;
    if (!text || text === "—") return;
    try {
      await navigator.clipboard.writeText(text);
      const prev = cCopy.textContent;
      cCopy.textContent = "تم النسخ ✓";
      setTimeout(() => { cCopy.textContent = prev; }, 1500);
    } catch {}
  });
})();

/* ============================================================
   MODULE 16 · Tools.Jwt — decoder & claims inspector
   ============================================================ */
(function initJwtTool() {
  const input = $id("jwtIn");
  const parts = $id("jwtParts");
  const hEl = $id("jwtHeader");
  const pEl = $id("jwtPayload");
  const sEl = $id("jwtSig");
  const warn = $id("jwtWarn");
  if (!input || !parts || !hEl || !pEl || !sEl || !warn) return;

  /**
   * Decode a Base64URL segment into UTF-8 text.
   * @param {string} seg Base64URL segment.
   * @returns {string} Decoded text.
   */
  function b64urlDecode(seg) {
    const b64 = seg.replace(/-/g, "+").replace(/_/g, "/");
    const padded = b64.length % 4 ? b64 + "=".repeat(4 - (b64.length % 4)) : b64;
    const bin = atob(padded);
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  }

  /** Recompute the decoded view from the current token. @returns {void} */
  function run() {
    const token = input.value.trim();
    if (!token) { parts.hidden = true; warn.textContent = ""; return; }

    const segs = token.split(".");
    hEl.textContent = pEl.textContent = sEl.textContent = "";
    let warnings = "";

    if (segs.length !== 3 || !segs[0] || !segs[1]) {
      parts.hidden = false;
      warn.textContent = "⚠ بنية غير صالحة: يجب أن يكون الرمز ثلاثة أجزاء مفصولة بنقطتين.";
      return;
    }

    try { hEl.textContent = JSON.stringify(JSON.parse(b64urlDecode(segs[0])), null, 2); }
    catch { warnings += "⚠ تعذّر فك ترويسة JSON. "; }

    let payload = {};
    try { payload = JSON.parse(b64urlDecode(segs[1])); }
    catch { warnings += "⚠ تعذّر فك حمولة JSON. "; }

    try {
      pEl.textContent = JSON.stringify(payload, null, 2);
      sEl.textContent = segs[2] || "(فارغ)";
      parts.hidden = false;

      if (payload.exp) {
        const ms = payload.exp * 1000;
        warnings += Date.now() > ms
          ? `✕ انتهت صلاحية الرمز في ${new Date(ms).toLocaleString("ar")}.`
          : `✓ الرمز صالح حتى ${new Date(ms).toLocaleString("ar")}.`;
      } else if (!warnings) {
        warnings = "لا يحتوي الرمز على حقل انتهاء صلاحية (exp).";
      }
      warn.textContent = warnings;
    } catch {
      parts.hidden = false;
      warn.textContent = warnings + "⚠ تعذّر فك ترميز Base64URL.";
    }
  }

  input.addEventListener("input", debounce(run, 200));
})(); 
 
/* ============================================================
   MODULE 17 · Tools.Cidr — IPv4 subnet calculator
   ============================================================ */
(function initCidrTool() {
  const ipEl = $id("cidrIp");
  const prefixEl = $id("cidrPrefix");
  const errEl = $id("cidrError");
  const tbody = document.querySelector("#cidrTableBody");
  if (!ipEl || !prefixEl || !errEl || !tbody) return;

  /**
   * Convert dotted IPv4 to a 32-bit unsigned integer.
   * @param {string} ip Dotted address.
   * @returns {number|null} Integer, or null when invalid.
   */
  function ipToInt(ip) {
    const octets = ip.split(".");
    if (octets.length !== 4) return null;
    let n = 0;
    for (const o of octets) {
      if (!/^\d{1,3}$/.test(o)) return null;
      const v = Number(o);
      if (v > 255) return null;
      n = n * 256 + v;
    }
    return n >>> 0;
  }

  /**
   * Convert a 32-bit unsigned integer to dotted notation.
   * @param {number} n Address integer.
   * @returns {string} Dotted address.
   */
  function intToIp(n) {
    return [(n >>> 24), (n >>> 16) & 255, (n >>> 8) & 255, n & 255].join(".");
  }

  /** Recalculate and render the subnet breakdown table. @returns {void} */
  function run() {
    const ipInt = ipToInt(ipEl.value.trim());
    let prefix = parseInt(prefixEl.value, 10);
    if (Number.isNaN(prefix)) prefix = 24;
    prefix = Math.min(32, Math.max(0, prefix));

    if (ipInt === null) {
      errEl.hidden = false;
      errEl.textContent = "أدخل عنوان IPv4 صحيحًا (مثال: 192.168.1.10).";
      tbody.innerHTML = "";
      return;
    }
    errEl.hidden = true;

    const mask = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
    const network = (ipInt & mask) >>> 0;
    const broadcast = (network | (~mask >>> 0)) >>> 0;
    const totalHosts = Math.pow(2, 32 - prefix);
    const usableHosts = prefix >= 31 ? totalHosts : Math.max(0, totalHosts - 2);
    const firstUsable = prefix >= 31 ? network : network + 1;
    const lastUsable = prefix >= 31 ? broadcast : broadcast - 1;

    const rows = [
      ["عنوان الشبكة", `${intToIp(network)} /${prefix}`],
      ["قناع الشبكة", intToIp(mask)],
      ["Wildcard Mask", intToIp((~mask >>> 0))],
      ["أول عنوان مضيف", intToIp(firstUsable)],
      ["آخر عنوان مضيف", intToIp(lastUsable)],
      ["عنوان البث (Broadcast)", intToIp(broadcast)],
      ["إجمالي العناوين", fmtInt(totalHosts)],
      ["المضيفون المتاحون", fmtInt(usableHosts)]
    ];
    tbody.innerHTML = rows
      .map(([k, v]) => `<tr><td>${escHtml(k)}</td><td>${escHtml(v)}</td></tr>`)
      .join("");
  }

  const runDebounced = debounce(run, 250);
  ipEl.addEventListener("input", runDebounced);
  prefixEl.addEventListener("input", runDebounced);
  run();
})(); 
 
/* ============================================================
   MODULE 18 · Tools.Password — entropy & strength analyzer
   ============================================================ */
(function initPasswordTool() {
  const input = $id("pwInput");
  const eye = $id("pwEye");
  const fill = $id("pwFill");
  const verdict = $id("pwVerdict");
  const list = $id("pwList");
  if (!input || !fill || !verdict || !list) return;

  /** Ubiquitous passwords treated as instant-fail. @type {string[]} */
  const COMMON = ["123456", "password", "qwerty", "111111", "abc123",
    "admin", "letmein", "iloveyou", "000000", "password1"];

  /**
   * Analyse a password: rules, character pool, entropy bits.
   * @param {string} pw Candidate password.
   * @returns {{rules:Object<string,boolean>,entropy:number}} Analysis.
   */
  /**
   * Keyboard / sequential / repeated-character patterns that indicate a
   * weak, predictable password regardless of raw entropy.
   * @param {string} pw
   * @returns {{keyboard:boolean, sequential:boolean, repeated:boolean, dedupe:number}}
   */
  function patternFlags(pw) {
    const lower = pw.toLowerCase();
    const keyboardRows = ["qwertyuiop", "asdfghjkl", "zxcvbnm", "1234567890"];
    let keyboard = false, sequential = false, repeated = false, runs = 0;
    const letters = lower.replace(/[^a-z]/g, "");
    const digits = lower.replace(/[^0-9]/g, "");

    // Repeated characters anywhere (e.g. "aaa", "111", "abab")
    for (let i = 0; i < pw.length - 1; i++) {
      if (pw[i] === pw[i + 1]) {
        repeated = true;
        runs++;
      }
    }

    // Keyboard runs (same row, adjacent keys) of length >= 4
    if (letters.length >= 4) {
      for (const row of keyboardRows) {
        for (let i = 0; i <= letters.length - 4; i++) {
          const slice = letters.slice(i, i + 4);
          if (row.includes(slice)) {
            // Allow forward or backward runs (e.g. "asdf" or "fghj" or "poiu")
            const forward = row.indexOf(slice) >= 0;
            const backward = row.indexOf(slice.split("").reverse().join("")) >= 0;
            if (forward || backward) keyboard = true;
          }
        }
      }
    }

    // Sequential letters or digits (abc, cba, 123, 321, etc.), length >= 3
    function hasSequential(str) {
      if (str.length < 3) return false;
      for (let i = 0; i <= str.length - 3; i++) {
        const a = str.charCodeAt(i), b = str.charCodeAt(i + 1), c = str.charCodeAt(i + 2);
        if (b - a === 1 && c - b === 1) return true;
        if (a - b === 1 && b - c === 1) return true;
      }
      return false;
    }
    if (hasSequential(letters)) sequential = true;
    if (hasSequential(digits)) sequential = true;

    return { keyboard, sequential, repeated, runs, short: pw.length < 8 };
  }

  /**
   * Analyse a password: rules, character pool, entropy bits, pattern flags.
   * @param {string} pw Candidate password.
   * @returns {{rules:Object<string,boolean>,entropy:number,flags:object}} Analysis.
   */
  function analyze(pw) {
    const rules = {
      len12: pw.length >= 12,
      len8: pw.length >= 8,
      case: /[a-z]/.test(pw) && /[A-Z]/.test(pw),
      digit: /\d/.test(pw),
      symbol: /[^A-Za-z0-9\s]/.test(pw),
      common: pw.length > 0 && !COMMON.some((c) => pw.toLowerCase().includes(c)),
      keyboardPattern: false,
      sequentialPattern: false,
      repeatedChars: false,
    };
    const flags = patternFlags(pw);
    rules.keyboardPattern = flags.keyboard;
    rules.sequentialPattern = flags.sequential;
    rules.repeatedChars = flags.repeated;

    let pool = 0;
    if (/[a-z]/.test(pw)) pool += 26;
    if (/[A-Z]/.test(pw)) pool += 26;
    if (/\d/.test(pw)) pool += 10;
    if (/[^A-Za-z0-9\s]/.test(pw)) pool += 33;
    if (/[\u0600-\u06FF]/.test(pw)) pool += 36; // Arabic letters
    const bits = pool > 0 ? Math.log2(pool) : 0; // guard: zero-pool input
    const entropy = pw.length ? +(pw.length * bits).toFixed(1) : 0;
    return { rules, entropy, flags };
  }

  /**
   * Humanise estimated offline crack time at 10⁴ guesses/sec.
   * @param {number} seconds Estimated seconds.
   * @returns {string} Readable Arabic duration.
   */
  function crackTime(seconds) {
    if (seconds < 1) return "أقل من ثانية";
    const units = [
      [31104000, "عام", "أعوام"],
      [2592000, "شهر", "أشهر"],
      [86400, "يوم", "أيام"],
      [3600, "ساعة", "ساعات"],
      [60, "دقيقة", "دقائق"]
    ];
    for (const [secs, one, many] of units) {
      if (seconds >= secs) {
        const v = Math.floor(seconds / secs);
        return `${fmtInt(v)} ${v === 1 ? one : many}`;
      }
    }
    return `${Math.floor(seconds)} ثانية`;
  }

  /** Recompute meter, verdict and checklist (delegates to worker). @returns {void} */
  async function run() {
    const pw = input.value;
    let analysis = null;
    if (pw) {
      try { analysis = await WorkerBridge.run("password", { password: pw }); } catch {}
      if (!analysis) analysis = analyze(pw); // main-thread fallback
    } else {
      analysis = analyze(pw);
    }
    var rules = analysis.rules;
    var entropy = analysis.entropy;

    $$("li", list).forEach((li) => {
      li.dataset.ok = String(Boolean(rules[li.dataset.rule]));
    });

    let cls = "";
    let label = pw ? "ضعيفة جدًا" : "ابدأ بالكتابة لتحليل القوة…";
    if (pw && entropy >= 80) { cls = "is-strong"; label = "قوية جدًا"; }
    else if (pw && entropy >= 60) { cls = "is-good"; label = "قوة جيدة"; }
    else if (pw && entropy >= 40) { cls = "is-fair"; label = "مقبولة"; }
    else if (pw) { cls = "is-weak"; }

    fill.className = `pw-meter-fill ${cls}`.trim();
    fill.style.width = pw ? `${Math.min(100, Math.round(entropy))}%` : "0%";

    var crackLabel = analysis.crackTime || crackTime(Math.pow(2, Math.min(entropy, 128)) / 2 / 10000);
    // Downgrade strength when predictable patterns exist, even if entropy is high.
    if (pw && (rules.keyboardPattern || rules.sequentialPattern || rules.repeatedChars || !rules.common)) {
      if (cls === "is-strong") { cls = "is-fair"; label = "مقبولة (بسبب أنماط متوقعة)"; }
      else if (cls === "is-good") { cls = "is-fair"; label = "مقبولة (بسبب أنماط متوقعة)"; }
    }
    verdict.textContent = pw
      ? `${label} — الإنتروبيا: ${entropy} بت · زمن الكسر التقديري: ${crackLabel} (تقديري — يعتمد على قوة الجهاز وهجوم القاموس)`
      : label;
  }

  if (eye) eye.addEventListener("click", () => {
    const show = input.type === "password";
    input.type = show ? "text" : "password";
    eye.setAttribute("aria-pressed", String(show));
    eye.setAttribute("aria-label", show ? "إخفاء كلمة المرور" : "إظهار كلمة المرور");
    eye.innerHTML = show ? ICON.eyeOff : ICON.eye;
  });

  input.addEventListener("input", run);
  run();
})(); 
 
/* ============================================================
   MODULE 19 · Tools.Encoders — Base64 / Hex / URL codecs
   ============================================================ */
(function initEncodersTool() {
  const tabs = $$(".enc-tab");
  const input = $id("encIn");
  const out = $id("encOut");
  const err = $id("encErr");
  const encodeBtn = $id("encEncode");
  const decodeBtn = $id("encDecode");
  const copyBtn = $id("encCopy");
  if (!input || !out || !err || !tabs.length || !encodeBtn || !decodeBtn) return;

  let mode = "b64";

  /** UTF-8 safe Base64 encode. @param {string} t Text. @returns {string} */
  function toB64(t) {
    const bytes = new TextEncoder().encode(t);
    let bin = "";
    for (let i = 0; i < bytes.length; i += 0x8000) {
      bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
    }
    return btoa(bin);
  }

  /** UTF-8 safe Base64 decode. @param {string} b Base64. @returns {string} */
  function fromB64(b) {
    const bin = atob(b.replace(/\s+/g, ""));
    return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
  }

  /** Hex-encode UTF-8 bytes. @param {string} t Text. @returns {string} */
  function toHex(t) {
    return [...new TextEncoder().encode(t)]
      .map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  /** Decode hex to UTF-8. @param {string} h Hex. @returns {string} */
  function fromHex(h) {
    const clean = h.replace(/\s+/g, "");
    if (clean.length % 2 || /[^0-9a-f]/i.test(clean)) throw new Error("bad hex");
    const bytes = new Uint8Array(clean.length / 2);
    for (let i = 0; i < bytes.length; i++) bytes[i] = parseInt(clean.substr(i * 2, 2), 16);
    return new TextDecoder().decode(bytes);
  }

  /**
   * Apply the active codec in the chosen direction.
   * @param {"encode"|"decode"} direction Operation direction.
   * @returns {void}
   */
  function apply(direction) {
    err.hidden = true;
    const value = input.value;
    if (!value) { out.textContent = "—"; return; }
    try {
      let result;
      if (mode === "b64") result = direction === "encode" ? toB64(value) : fromB64(value);
      else if (mode === "hex") result = direction === "encode" ? toHex(value) : fromHex(value);
      else result = direction === "encode"
        ? encodeURIComponent(value)
        : decodeURIComponent(value.replace(/\+/g, " "));
      out.textContent = result;
    } catch {
      out.textContent = "—";
      err.hidden = false;
      err.textContent = "المدخل غير صالح لفك الترميز بهذه الصيغة.";
    }
  }

  tabs.forEach((tab) => tab.addEventListener("click", () => {
    tabs.forEach((t) => t.setAttribute("aria-pressed", String(t === tab)));
    mode = tab.dataset.enc;
  }));
  encodeBtn.addEventListener("click", () => apply("encode"));
  decodeBtn.addEventListener("click", () => apply("decode"));
  if (copyBtn) copyBtn.addEventListener("click", async () => {
    if (!out.textContent || out.textContent === "—") return;
    try {
      await navigator.clipboard.writeText(out.textContent);
      copyBtn.textContent = "تم النسخ ✓";
      setTimeout(() => { copyBtn.textContent = "نسخ"; }, 1500);
    } catch {}
  });
})(); 
 
/* ============================================================
   MODULE 21 · MaterialsFilter — live search + tag chips
   ============================================================ */
(function initMaterialsFilter() {
  const grid = document.querySelector(".work-grid");
  const input = $id("subjectSearch");
  const countEl = $id("resultsCount");
  const emptyEl = $id("emptyState");
  const chips = $$("#subjects .tag-row .tag-chip");
  if (!grid || !input || !chips.length) return;
  const cards = $$(".work-card", grid);

  let activeTag = "all";

  /** Apply the combined search query + active tag to all cards. @returns {void} */
  function applyFilters() {
    const q = input.value.trim().toLowerCase();
    let visible = 0;

    cards.forEach((card) => {
      const tags = (card.dataset.tags || "").split(/\s+/).filter(Boolean);
      const text = card.textContent.toLowerCase();
      const tagOk = activeTag === "all" || tags.includes(activeTag);
      const textOk = !q || text.includes(q);
      const show = tagOk && textOk;
      card.classList.toggle("is-hidden", !show);
      if (show) visible++;
    });

    if (countEl) countEl.textContent = `عرض ${visible} من ${cards.length} مادة`;
    if (emptyEl) emptyEl.hidden = visible !== 0;
    grid.classList.toggle("is-empty", visible === 0);
  }

  input.addEventListener("input", applyFilters);
  chips.forEach((chip) =>
    chip.addEventListener("click", () => {
      chips.forEach((c) => c.setAttribute("aria-pressed", String(c === chip)));
      activeTag = chip.dataset.tag;
      applyFilters();
    })
  );

  applyFilters();
})();

