    const key = ev.key;
    if (key !== "ArrowLeft" && key !== "ArrowRight" && key !== "Home" && key !== "End") return;
    const ltr = !!(document.documentElement && document.documentElement.dir === "ltr");
    const forward = ltr ? "ArrowRight" : "ArrowLeft";
    const back = ltr ? "ArrowLeft" : "ArrowRight";
