    pcLbl.setAttribute("for", "gpaPriorCredits");
    const pgLbl = el("label", "student-lbl", T("gpa.priorGpa"));
    const pgIn = el("input", "student-input");
    pgIn.type = "number"; pgIn.min = "0"; pgIn.step = "0.01"; pgIn.id = "gpaPriorGpa";
