    target.appendChild(el("h4", "student-h4", T("gpa.targetTitle")));
    const tLbl = el("label", "student-lbl", T("gpa.target"));
    const tIn = el("input", "student-input");
    tIn.type = "number"; tIn.min = "0"; tIn.max = String(scale().max); tIn.step = "0.01";
    tIn.id = "gpaTarget";
