    shell.appendChild(el("p", "student-note", T("gpa.note")));
    shell.appendChild(el("p", "student-note student-note-soft", T("student.localNote")));
    const reset = el("button", "student-btn btn btn-sm btn-ghost", T("gpa.reset"));
