    wrap.appendChild(el("p", "theatre-outcome-choice", pick(c.label)));
    wrap.appendChild(el("p", "theatre-outcome-why-label", T("theatre.why")));
    wrap.appendChild(el("p", "theatre-outcome-why", pick(c.why)));

